import math
from dataclasses import dataclass
from typing import Generic, TypeVar

T = TypeVar("T")

@dataclass(frozen=True)
class Some(Generic[T]):
    value: T

@dataclass(frozen=True)
class Nothing:
    pass

type Option[T] = Some[T] | Nothing

def safeSqrt(n: float) -> Option[float]:
    """
    Returns Some(sqrt(n)) if n >= 0, otherwise returns Nothing.
    """
    if n < 0:
        return Nothing()
    return Some(math.sqrt(n))

def main() -> None:
    # Test cases as specified: safeSqrt(16.0) and safeSqrt(-4.0)
    test_values = [16.0, -4.0]

    for val in test_values:
        result = safeSqrt(val)

        match result:
            case Some(value):
                print(f"Root: {value}")
            case Nothing():
                print("Error: Negative input")

if __name__ == "__main__":
    main()

