pure func isBalancedChars(cs: [string], count: int) -> bool =
  if count < 0 then false
  else match cs {
    [] => count == 0,
    c :: rest => if c == "(" then isBalancedChars(rest, count + 1) else if c == ")" then isBalancedChars(rest, count - 1) else isBalancedChars(rest, count)
  }

pure func isBalanced(s: string) -> bool =
  isBalancedChars(chars(s), 0)

