module benchmark/solution

type Mat = Mat(int, int, int, int, int, int, int, int, int)

pure func mul(a: Mat, b: Mat) -> Mat =
  match a {
    Mat(a00, a01, a02, a10, a11, a12, a20, a21, a22) =>
      match b {
        Mat(b00, b01, b02, b10, b11, b12, b20, b21, b22) =>
          let m = 1000000007 in
          let c00 = (a00 * b00 + a01 * b10 + a02 * b20) % m in
          let c01 = (a00 * b01 + a01 * b11 + a02 * b21) % m in
          let c02 = (a00 * b02 + a01 * b12 + a02 * b22) % m in
          let c10 = (a10 * b00 + a11 * b10 + a12 * b20) % m in
          let c11 = (a10 * b01 + a11 * b11 + a12 * b21) % m in
          let c12 = (a10 * b02 + a11 * b12 + a12 * b22) % m in
          let c20 = (a20 * b00 + a21 * b10 + a22 * b20) % m in
          let c21 = (a20 * b01 + a21 * b11 + a22 * b21) % m in
          let c22 = (a20 * b02 + a21 * b12 + a22 * b22) % m in
          Mat(c00, c01, c02, c10, c11, c12, c20, c21, c22)
      }
  }

pure func matPow(a: Mat, n: int) -> Mat =
  if n == 0 then Mat(1, 0, 0, 0, 1, 0, 0, 0, 1)
  else if n % 2 == 0 then
    let half = matPow(a, n / 2) in
    mul(half, half)
  else mul(a, matPow(a, n - 1))

pure func solve(n: int) -> int =
  let initA = Mat(1, 0, 1, 1, 1, 0, 0, 1, 0) in
  let resMat = matPow(initA, n) in
  match resMat {
    Mat(m00, m01, m02, m10, m11, m12, m20, m21, m22) =>
      (m00 + m10 + m20) % 1000000007
  }

export func main() -> () ! {IO} {
  let n1 = 1000000000000000000;
  let n2 = 987654321987654321;
  println(show(solve(n1)));
  println(show(solve(n2)))
}

