}

module benchmark/solution

import std/io (println)
import std/list (nth, reverse)

type Instr =
    Push(int)
  | Add
  | Sub
  | Mul
  | Dup
  | Over
  | Swap
  | Pop
  | Jmp(int)
  | Jmpz(int)
  | Jmpgt(int)
  | Halt

type State = {
  stack: [int],
  pc: int,
  steps: int
}

pure func step(prog: [Instr], state: State) -> (State, bool) =
  match nth(prog, state.pc) {
    None => (state, false),
    Some(instr) => {
      let nextSteps = state.steps + 1;
      match instr {
        Push(k) =>
          ({ stack: k :: state.stack, pc: state.pc + 1, steps: nextSteps }, true),

        Add =>
          match state.stack {
            b :: a :: rest =>
              ({ stack: (a + b) :: rest, pc: state.pc + 1, steps: nextSteps }, true),
            _ => (state, false)
          },

        Sub =>
          match state.stack {
            b :: a :: rest =>
              ({ stack: (a - b) :: rest, pc: state.pc + 1, steps: nextSteps }, true),
            _ => (state, false)
          },

        Mul =>
          match state.stack {
            b :: a :: rest =>
              ({ stack: (a * b) :: rest, pc: state.pc + 1, steps: nextSteps }, true),
            _ => (state, false)
          },

        Dup =>
          match state.stack {
            a :: rest =>
              ({ stack: a :: a :: rest, pc: state.pc + 1, steps: nextSteps }, true),
            _ => (state, false)
          },

        Over =>
          match state.stack {
            b :: a :: rest =>
              ({ stack: a :: b :: a :: rest, pc: state.pc + 1, steps: nextSteps }, true),
            _ => (state, false)
          },

        Swap =>
          match state.stack {
            b :: a :: rest =>
              ({ stack: a :: b :: rest, pc: state.pc + 1, steps: nextSteps }, true),
            _ => (state, false)
          },

        Pop =>
          match state.stack {
            _ :: rest =>
              ({ stack: rest, pc: state.pc + 1, steps: nextSteps }, true),
            _ => (state, false)
          },

        Jmp(d) =>
          ({ stack: state.stack, pc: state.pc + d, steps: nextSteps }, true),

        Jmpz(d) =>
          match state.stack {
            v :: rest =>
              ({ stack: rest, pc: if v == 0 then state.pc + d else state.pc + 1, steps: nextSteps }, true),
            _ => (state, false)
          },

        Jmpgt(d) =>
          match state.stack {
            b :: a :: rest =>
              ({ stack: rest, pc: if a > b then state.pc + d else state.pc + 1, steps: nextSteps }, true),
            _ => (state, false)
          },

        Halt =>
          ({ stack: state.stack, pc: state.pc, steps: nextSteps }, false)
      }
    }
  }

pure func run(prog: [Instr], state: State) -> State =
  match step(prog, state) {
    (nextState, true) => run(prog, nextState),
    (nextState, false) => nextState
  }

func printStack(st: [int]) -> () ! {IO} =
  match st {
    [] => (),
    x :: rest => {
      println(show(x));
      printStack(rest)
    }
  }

export func main() -> () ! {IO} {
  let prog = [
    Push(252),
    Push(105),
    Over,
    Over,
    Sub,
    Jmpz(12),
    Over,
    Over,
    Jmpgt(4),
    Over,
    Sub,
    Jmp(-9),
    Swap,
    Over,
    Sub,
    Swap,
    Jmp(-14),
    Pop,
    Halt
  ];
  let initialState = { stack: [], pc: 0, steps: 0 };
  let finalState = run(prog, initialState);
  printStack(reverse(finalState.stack));
  println("steps: ${show(finalState.steps)}")
}

