module benchmark/solution

import std/env (getArgs)
import std/fs (readFile)
import std/string (split, trim, stringToInt)

func parseAndSum(lines: [string]) -> int =
  match lines {
    [] => 0,
    line :: rest =>
      let cleaned = trim(line) in
      if cleaned == "" then parseAndSum(rest)
      else match stringToInt(cleaned) {
        Some(n) => n + parseAndSum(rest),
        None => parseAndSum(rest)
      }
  }

export func main() -> () ! {IO, FS, Env} {
  let args = getArgs();
  match args {
    filename :: _ => {
      let content = readFile(filename);
      let lines = split(content, "\n");
      let total = parseAndSum(lines);
      println(show(total))
    },
    [] => ()
  }
}

