#!/usr/bin/env python3
"""Sum the numbers contained in a file, one per line."""

from __future__ import annotations

import sys
from pathlib import Path


def parse_numbers(text: str) -> list[float]:
    """Parse whitespace/newline separated numbers, ignoring blank lines."""
    numbers: list[float] = []
    for lineno, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped:
            continue
        try:
            numbers.append(float(stripped))
        except ValueError as exc:
            raise ValueError(f"line {lineno}: {stripped!r} is not a number") from exc
    return numbers


def format_total(total: float) -> str:
    """Print integral totals without a trailing '.0'."""
    if total == int(total):
        return str(int(total))
    return repr(total)


def main(argv: list[str]) -> int:
    if len(argv) != 2:
        print(f"usage: {Path(argv[0]).name} FILENAME", file=sys.stderr)
        return 2

    path = Path(argv[1])
    try:
        text = path.read_text(encoding="utf-8")
    except OSError as exc:
        print(f"error: cannot read {path}: {exc}", file=sys.stderr)
        return 1

    try:
        numbers = parse_numbers(text)
    except ValueError as exc:
        print(f"error: {path}: {exc}", file=sys.stderr)
        return 1

    print(format_total(sum(numbers)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

codeSamples.ailang:
module benchmark/solution

import std/io (println)
import std/string (contains, chars)
import std/list (take, drop, length, nth, reverse)
import std/option (Option, Some, None)

type Run = {
  id: int,
  startIndex: int,
  origLen: int,
  remLen: int,
  canOpen: bool,
  canClose: bool
}

type Match = {
  openerId: int,
  closerId: int,
  isStrong: bool
}

pure func isPunct(c: string) -> bool {
  if c == "" then false
  else contains("!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~", c)
}

pure func isWS(c: string) -> bool {
  c == " " || c == ""
}

pure func isLeftFlanking(charBefore: string, charAfter: string) -> bool {
  if isWS(charAfter) then false
  else if not isPunct(charAfter) then true
  else isWS(charBefore) || isPunct(charBefore)
}

pure func isRightFlanking(charBefore: string, charAfter: string) -> bool {
  if isWS(charBefore) then false
  else if not isPunct(charBefore) then true
  else isWS(charAfter) || isPunct(charAfter)
}

pure func getChar(cs: [string], idx: int) -> string {
  match nth(cs, idx) {
    Some(ch) => ch,
    None => ""
  }
}

pure func countStars(cs: [string], pos: int) -> int {
  match nth(cs, pos) {
    Some(ch) => if ch == "*" then 1 + countStars(cs, pos + 1) else 0,
    None => 0
  }
}

pure func parseRunsAndTexts(cs: [string], pos: int, runId: int, curText: string, accTexts: [string], accRuns: [Run]) -> ([string], [Run]) {
  if pos >= length(cs) then
    (reverse(curText :: accTexts), reverse(accRuns))
  else {
    let ch = getChar(cs, pos);
    if ch == "*" then {
      let runLen = countStars(cs, pos);
      let charBefore = if pos == 0 then "" else getChar(cs, pos - 1);
      let charAfter = if pos + runLen >= length(cs) then "" else getChar(cs, pos + runLen);
      let leftF = isLeftFlanking(charBefore, charAfter);
      let rightF = isRightFlanking(charBefore, charAfter);
      let run = { id: runId, startIndex: pos, origLen: runLen, remLen: runLen, canOpen: leftF, canClose: rightF };
      parseRunsAndTexts(cs, pos + runLen, runId + 1, "", curText :: accTexts, run :: accRuns)
    } else {
      parseRunsAndTexts(cs, pos + 1, runId, "${curText}${ch}", accTexts, accRuns)
    }
  }
}

pure func removeAt(xs: [Run], idx: int) -> [Run] {
  take(idx, xs) ++ drop(idx + 1, xs)
}

pure func updateRunRemLen(runs: [Run], idToUpdate: int, newRem: int) -> [Run] {
  match runs {
    [] => [],
    r :: rest =>
      if r.id == idToUpdate then { r | remLen: newRem } :: rest
      else r :: updateRunRemLen(rest, idToUpdate, newRem)
  }
}

pure func findOpener(activeRuns: [Run], searchIdx: int, closer: Run) -> Option[int] {
  if searchIdx < 0 then None
  else match nth(activeRuns, searchIdx) {
    None => None,
    Some(cand) =>
      if cand.remLen > 0 && cand.canOpen then {
        let sumOrig = cand.origLen + closer.origLen;
        let rule3Blocked = (closer.canOpen || cand.canClose) && (sumOrig % 3 == 0) && not (cand.origLen % 3 == 0 && closer.origLen % 3 == 0);
        if not rule3Blocked then Some(searchIdx)
        else findOpener(activeRuns, searchIdx - 1, closer)
      } else {
        findOpener(activeRuns, searchIdx - 1, closer)
      }
  }
}

pure func runMatches(activeRuns: [Run], cursor: int, matches: [Match], finalRuns: [Run]) -> ([Match], [Run]) {
  if cursor >= length(activeRuns) then (matches, finalRuns)
  else match nth(activeRuns, cursor) {
    None => (matches, finalRuns),
    Some(closer) =>
      if closer.remLen == 0 || not closer.canClose then
        runMatches(activeRuns, cursor + 1, matches, finalRuns)
      else match findOpener(activeRuns, cursor - 1, closer) {
        None =>
          if not closer.canOpen then {
            let newActive = removeAt(activeRuns, cursor);
            runMatches(newActive, cursor, matches, finalRuns)
          } else {
            runMatches(activeRuns, cursor + 1, matches, finalRuns)
          },
        Some(opIdx) =>
          match nth(activeRuns, opIdx) {
            None => (matches, finalRuns),
            Some(opener) => {
              let isStrong = opener.remLen >= 2 && closer.remLen >= 2;
              let consume = if isStrong then 2 else 1;
              let newM = { openerId: opener.id, closerId: closer.id, isStrong: isStrong };
              let matches2 = matches ++ [newM];
              let newOpRem = opener.remLen - consume;
              let newClRem = closer.remLen - consume;
              let finalRuns1 = updateRunRemLen(finalRuns, opener.id, newOpRem);
              let finalRuns2 = updateRunRemLen(finalRuns1, closer.id, newClRem);

              let openerList = if newOpRem > 0 then [{ opener | remLen: newOpRem }] else [];
              let closerList = if newClRem > 0 then [{ closer | remLen: newClRem }] else [];
              let newActive = take(opIdx, activeRuns) ++ openerList ++ closerList ++ drop(cursor + 1, activeRuns);
              let newCursor = opIdx + (if newOpRem > 0 then 1 else 0);
              runMatches(newActive, newCursor, matches2, finalRuns2)
            }
          }
      }
  }
}

pure func filterClosers(ms: [Match], rId: int) -> [Match] {
  match ms {
    [] => [],
    m :: rest => if m.closerId == rId then m :: filterClosers(rest, rId) else filterClosers(rest, rId)
  }
}

pure func filterOpeners(ms: [Match], rId: int) -> [Match] {
  match ms {
    [] => [],
    m :: rest => if m.openerId == rId then m :: filterOpeners(rest, rId) else filterOpeners(rest, rId)
  }
}

pure func closingTagsToStr(ms: [Match]) -> string {
  match ms {
    [] => "",
    m :: rest => {
      let tag = if m.isStrong then "</strong>" else "</em>";
      "${tag}${closingTagsToStr(rest)}"
    }
  }
}

pure func openingTagsToStr(ms: [Match]) -> string {
  match ms {
    [] => "",
    m :: rest => {
      let tag = if m.isStrong then "<strong>" else "<em>";
      "${tag}${openingTagsToStr(rest)}"
    }
  }
}

pure func repeatStar(n: int) -> string {
  if n <= 0 then "" else "*${repeatStar(n - 1)}"
}

pure func getFinalRemLen(finalRuns: [Run], rId: int) -> int {
  match finalRuns {
    [] => 0,
    r :: rest => if r.id == rId then r.remLen else getFinalRemLen(rest, rId)
  }
}

pure func renderRun(rId: int, matches: [Match], finalRuns: [Run]) -> string {
  let closers = filterClosers(matches, rId);
  let openers = reverse(filterOpeners(matches, rId));
  let closeStr = closingTagsToStr(closers);
  let openStr = openingTagsToStr(openers);
  let rem = getFinalRemLen(finalRuns, rId);
  let remStr = repeatStar(rem);
  "${closeStr}${remStr}${openStr}"
}

pure func assembleLine(texts: [string], rId: int, totalRuns: int, matches: [Match], finalRuns: [Run]) -> string {
  let t = match nth(texts, rId) { Some(s) => s, None => "" };
  if rId >= totalRuns then t
  else {
    let runStr = renderRun(rId, matches, finalRuns);
    let restStr = assembleLine(texts, rId + 1, totalRuns, matches, finalRuns);
    "${t}${runStr}${restStr}"
  }
}

pure func processLine(line: string) -> string {
  let cs = chars(line);
  match parseRunsAndTexts(cs, 0, 0, "", [], []) {
    (texts, runs) =>
      match runMatches(runs, 0, [], runs) {
        (matches, finalRuns) =>
          assembleLine(texts, 0, length(runs), matches, finalRuns)
      }
  }
}

func processAll(lines: [string]) -> () ! {IO} {
  match lines {
    [] => (),
    line :: rest => {
      println(processLine(line));
      processAll(rest)
    }
  }
}

export func main() -> () ! {IO} {
  let lines = [
    "*wind mill*",
    "a * lantern glow*",
    "**tide**pool",
    "***quartz***",
    "**quiet*",
    "*ember**",
    "*sky**lark**dawn*",
    "*moss**fern*",
    "***husk*kernel**",
    "**pearl**shell**",
    "*a*b*c*",
    "escape**not*done"
  ];
  processAll(lines)
}

