@dataclass
class Node:
    left: BST
    value: int
    right: BST


BST = Union[Leaf, Node]


def insert(tree: BST, val: int) -> BST:
    match tree:
        case Leaf():
            return Node(Leaf(), val, Leaf())
        case Node(left, value, right):
            if val < value:
                return Node(insert(left, val), value, right)
            elif val > value:
                return Node(left, value, insert(right, val))
            else:
                return tree


def contains(tree: BST, val: int) -> bool:
    match tree:
        case Leaf():
            return False
        case Node(left, value, right):
            if val == value:
                return True
            elif val < value:
                return contains(left, val)
            else:
                return contains(right, val)


def size(tree: BST) -> int:
    match tree:
        case Leaf():
            return 0
        case Node(left, _, right):
            return 1 + size(left) + size(right)


def isBST(tree: BST, lo: int, hi: int) -> bool:
    match tree:
        case Leaf():
            return True
        case Node(left, value, right):
            return lo < value < hi and isBST(left, lo, value) and isBST(right, value, hi)


