import re


def encode(s: str) -> str:
    if not s:
        return ""
    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(f"{count}{s[i - 1]}")
            count = 1
    result.append(f"{count}{s[-1]}")
    return "".join(result)


def decode(s: str) -> str:
    if not s:
        return ""
    result = []
    for match in re.finditer(r"(\d+)(.)", s):
        count = int(match.group(1))
        char = match.group(2)
        result.append(char * count)
    return "".join(result)


def roundtrip(s: str) -> bool:
    return decode(encode(s)) == s


def single_char_encode(c: str) -> str:
    return encode(c)


def main():
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print(roundtrip("hello"))
