def toRoman(n: int) -> str:
    if not 1 <= n <= 3999:
        raise ValueError(f"Input must be between 1 and 3999, got {n}")
    result = []
    for value, numeral in ROMAN_NUMERALS:
        while n >= value:
            result.append(numeral)
            n -= value
    return "".join(result)


def fromRoman(s: str) -> int:
    roman_values = {
        "I": 1, "V": 5, "X": 10, "L": 50,
        "C": 100, "D": 500, "M": 1000
    }
    result = 0
    prev = 0
    for ch in reversed(s):
        curr = roman_values[ch]
        if curr < prev:
            result -= curr
        else:
            result += curr
        prev = curr
    return result


def roundtrip(n: int) -> bool:
    return fromRoman(toRoman(n)) == n


def distinctEncoding(a: int, b: int) -> bool:
    return toRoman(a) != toRoman(b)


