    SCons(_, rest) => 1 + sLength(rest)
  }

func isSorted(s: Set) -> bool =
  match s {
    SNil => true,
    SCons(_, SNil) => true,
    SCons(x, SCons(y, rest)) => x < y && isSorted(SCons(y, rest))
  }

func sMerge(s1: Set, s2: Set) -> Set =
  match s1 {
    SNil => s2,
    SCons(x, rest1) => match s2 {
      SNil => s1,
      SCons(y, rest2) =>
        if x < y then SCons(x, sMerge(rest1, s2))
        else if y < x then SCons(y, sMerge(s1, rest2))
        else SCons(x, sMerge(rest1, rest2))
    }
  }

func sIntersect(s1: Set, s2: Set) -> Set =
  match s1 {
    SNil => SNil,
    SCons(x, rest1) => match s2 {
      SNil => SNil,
      SCons(y, rest2) =>
        if x < y then sIntersect(rest1, s2)
        else if y < x then sIntersect(s1, rest2)
        else SCons(x, sIntersect(rest1, rest2))
