from __future__ import annotations
from dataclasses import dataclass
from typing import Union


# ADT definition for sorted integer sets
@dataclass(frozen=True)
class SNil:
    pass


@dataclass(frozen=True)
class SCons:
    head: int
    tail: SortedSet


SortedSet = Union[SNil, SCons]


def sMerge(a: SortedSet, b: SortedSet) -> SortedSet:
    """Union of two sorted sets, preserving sorted + no-duplicates invariant."""
    match (a, b):
        case (SNil(), _):
            return b
        case (_, SNil()):
            return a
        case (SCons(ha, ta), SCons(hb, tb)):
            if ha < hb:
                return SCons(ha, sMerge(ta, b))
            elif ha > hb:
                return SCons(hb, sMerge(a, tb))
            else:  # ha == hb, include once
                return SCons(ha, sMerge(ta, tb))


def sIntersect(a: SortedSet, b: SortedSet) -> SortedSet:
    """Intersection of two sorted sets, preserving sorted + no-duplicates invariant."""
    match (a, b):
        case (SNil(), _) | (_, SNil()):
            return SNil()
        case (SCons(ha, ta), SCons(hb, tb)):
            if ha < hb:
                return sIntersect(ta, b)
            elif ha > hb:
                return sIntersect(a, tb)
            else:  # ha == hb
                return SCons(ha, sIntersect(ta, tb))


def sLength(s: SortedSet) -> int:
    """Return the number of elements in the sorted set."""
    match s:
        case SNil():
            return 0
        case SCons(_, tail):
            return 1 + sLength(tail)


def isSorted(s: SortedSet) -> bool:
    """Check that the set is strictly sorted (no duplicates, ascending order)."""
    match s:
        case SNil():
            return True
        case SCons(h, SNil()):
            return True
        case SCons(h, SCons(h2, _) as tail):
            return h < h2 and isSorted(tail)


def toStr(s: SortedSet) -> str:
    """Convert a sorted set to a string representation."""
    elements = []
    current = s
    while isinstance(current, SCons):
        elements.append(str(current.head))
        current = current.tail
    return "{" + ", ".join(elements) + "}"


def mergePreservesSorted(a: SortedSet, b: SortedSet) -> bool:
    """Proof: the merge (union) of two sorted sets is also sorted."""
    return isSorted(sMerge(a, b))


def inclusionExclusion(a: SortedSet, b: SortedSet) -> bool:
    """Proof of inclusion-exclusion principle: |A∪B| + |A∩B| == |A| + |B|."""
    return sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b)


def main() -> None:
    a = SCons(1, SCons(3, SCons(5, SNil())))
    b = SCons(2, SCons(3, SCons(4, SNil())))

    print(toStr(sMerge(a, b)))
    print(toStr(sIntersect(a, b)))
    print(sLength(sMerge(a, b)))
    print(isSorted(sMerge(a, b)))
    print(mergePreservesSorted(a, b))
    print(inclusionExclusion(a, b))


if __name__ == "__main__":
    main()

