func countMultiples(n: int, limit: int) -> int {
  if n > limit then 0
  else {
    let condition = (n != 0) && ((n % 3 == 0) || (n % 5 == 0));
    let matches = if condition then 1 else 0;
    matches + countMultiples(n + 1, limit)
  }
