import std/option (Option, Some, None)
import std/list (sortBy)

func lookupAssignment(name: string, assign: [{ name: string, ver: int }]) -> Option[int] =
  match assign {
    [] => None,
    a :: rest => if a.name == name then Some(a.ver) else lookupAssignment(name, rest)
  }

func getRequirements(pkgName: string, pkgVer: int, universe: [{ name: string, ver: int, reqs: [{ name: string, lo: int, hi: int }] }]) -> [{ name: string, lo: int, hi: int }] =
  match universe {
    [] => [],
    p :: rest =>
      if p.name == pkgName && p.ver == pkgVer then p.reqs
      else getRequirements(pkgName, pkgVer, rest)
  }

func filterCandidates(pkgName: string, lo: int, hi: int, universe: [{ name: string, ver: int, reqs: [{ name: string, lo: int, hi: int }] }]) -> [int] =
  match universe {
    [] => [],
    p :: rest =>
      if p.name == pkgName && p.ver >= lo && p.ver <= hi then p.ver :: filterCandidates(pkgName, lo, hi, rest)
      else filterCandidates(pkgName, lo, hi, rest)
  }

func cmpDesc(a: int, b: int) -> int = b - a

func getCandidates(pkgName: string, lo: int, hi: int, universe: [{ name: string, ver: int, reqs: [{ name: string, lo: int, hi: int }] }]) -> [int] {
  let raw = filterCandidates(pkgName, lo, hi, universe);
  sortBy(cmpDesc, raw)
}

func tryCandidates(candidates: [int], pkgName: string, restWorklist: [{ name: string, lo: int, hi: int }], assign: [{ name: string, ver: int }], universe: [{ name: string, ver: int, reqs: [{ name: string, lo: int, hi: int }] }]) -> Option[[{ name: string, ver: int }]] =
  match candidates {
    [] => None,
    candVer :: restCands => {
      let newAssign = { name: pkgName, ver: candVer } :: assign;
      let newReqs = getRequirements(pkgName, candVer, universe);
      let newWorklist = newReqs ++ restWorklist;
      match resolve(newWorklist, newAssign, universe) {
        Some(res) => Some(res),
        None => tryCandidates(restCands, pkgName, restWorklist, assign, universe)
      }
    }
  }

func resolve(worklist: [{ name: string, lo: int, hi: int }], assign: [{ name: string, ver: int }], universe: [{ name: string, ver: int, reqs: [{ name: string, lo: int, hi: int }] }]) -> Option[[{ name: string, ver: int }]] =
  match worklist {
    [] => Some(assign),
    req :: restWorklist =>
      match lookupAssignment(req.name, assign) {
        Some(v) =>
          if v >= req.lo && v <= req.hi then
            resolve(restWorklist, assign, universe)
          else
            None,
        None => {
          let cands = getCandidates(req.name, req.lo, req.hi, universe);
          tryCandidates(cands, req.name, restWorklist, assign, universe)
        }
      }
  }

func cmpAssign(a: { name: string, ver: int }, b: { name: string, ver: int }) -> int =
  if a.name < b.name then -1
  else if a.name > b.name then 1
  else 0

func printAssignments(assigns: [{ name: string, ver: int }]) -> () ! {IO} =
  match assigns {
    [] => (),
    a :: rest => {
      println("${a.name}=${show(a.ver)}");
      printAssignments(rest)
    }
  }

func runUniverse(universe: [{ name: string, ver: int, reqs: [{ name: string, lo: int, hi: int }] }]) -> () ! {IO} {
  let initAssign = [{ name: "app", ver: 1 }];
  let initWorklist = getRequirements("app", 1, universe);
  match resolve(initWorklist, initAssign, universe) {
    Some(result) => {
      println("resolved");
      let sorted = sortBy(cmpAssign, result);
      printAssignments(sorted)
    },
    None => println("conflict")
  }
}

export func main() -> () ! {IO} {
  let univA = [
    { name: "app", ver: 1, reqs: [{ name: "lib", lo: 1, hi: 3 }, { name: "util", lo: 3, hi: 3 }] },
    { name: "lib", ver: 3, reqs: [{ name: "core", lo: 3, hi: 3 }] },
    { name: "lib", ver: 2, reqs: [{ name: "core", lo: 1, hi: 2 }] },
    { name: "lib", ver: 1, reqs: [] },
    { name: "util", ver: 3, reqs: [{ name: "core", lo: 1, hi: 1 }] },
    { name: "core", ver: 3, reqs: [] },
    { name: "core", ver: 2, reqs: [] },
    { name: "core", ver: 1, reqs: [] }
  ];
  let univB = [
    { name: "app", ver: 1, reqs: [{ name: "x", lo: 1, hi: 1 }, { name: "y", lo: 1, hi: 1 }] },
    { name: "x", ver: 1, reqs: [{ name: "core", lo: 1, hi: 1 }] },
    { name: "y", ver: 1, reqs: [{ name: "core", lo: 2, hi: 2 }] },
    { name: "core", ver: 2, reqs: [] },
    { name: "core", ver: 1, reqs: [] }
  ];
  runUniverse(univA);
  runUniverse(univB)
}

