def solve():
    universe_a = {
        ("app", 1): [("lib", 1, 3), ("util", 3, 3)],
        ("lib", 3): [("core", 3, 3)],
        ("lib", 2): [("core", 1, 2)],
        ("lib", 1): [],
        ("util", 3): [("core", 1, 1)],
        ("core", 3): [],
        ("core", 2): [],
        ("core", 1): [],
    }

    universe_b = {
        ("app", 1): [("x", 1, 1), ("y", 1, 1)],
        ("x", 1): [("core", 1, 1)],
        ("y", 1): [("core", 2, 2)],
        ("core", 2): [],
        ("core", 1): [],
    }

    def get_versions(universe, pkg_name):
        versions = []
        for (name, ver) in universe:
            if name == pkg_name:
                versions.append(ver)
        return sorted(versions, reverse=True)

    def resolve(universe):
        assignment = {"app": 1}
        initial_reqs = list(universe.get(("app", 1), []))

        def backtrack(worklist, assignment):
            if not worklist:
                return dict(assignment)

            req = worklist[0]
            rest = worklist[1:]
            dep_name, lo, hi = req

            if dep_name in assignment:
                assigned_ver = assignment[dep_name]
                if lo <= assigned_ver <= hi:
                    return backtrack(rest, assignment)
                else:
                    return None
            else:
                candidates = [v for v in get_versions(universe, dep_name) if lo <= v <= hi]
                for candidate in candidates:
                    assignment[dep_name] = candidate
                    dep_reqs = list(universe.get((dep_name, candidate), []))
                    new_worklist = dep_reqs + rest
                    result = backtrack(new_worklist, assignment)
                    if result is not None:
                        return result
                    del assignment[dep_name]
                return None

        return backtrack(initial_reqs, assignment)

    for universe in [universe_a, universe_b]:
        result = resolve(universe)
        if result is None:
            print("conflict")
        else:
            print("resolved")
            for name in sorted(result.keys()):
                print(f"{name}={result[name]}")


if __name__ == "__main__":
    solve()

