import std/xml (parse, findAll, findFirst, getText, getAttr, getChildren, getTag, XmlNode)
import std/option (Some, None)
import std/result (Ok, Err)
import std/list (map, length as listLength)
import docparse/types/document (Block, TextBlock, HeadingBlock, ListBlock, TableBlock, TableCell, DocMetadata, emptyMetadata, simpleCell, mkTable)
import docparse/services/zip_extract (readDocxContent)

-- Get style attribute from paragraph
pure func getParagraphStyle(pNode: XmlNode) -> string = {
  match findFirst(pNode, "w:pStyle") {
    Some(styleNode) => {
      match getAttr(styleNode, "w:val") {
        Some(val) => val,
        None => ""
      }
    },
    None => ""
  }
}

-- Check if paragraph is a list item
pure func isListItem(pNode: XmlNode) -> bool = {
  match findFirst(pNode, "w:numPr") {
    Some(_) => true,
    None => false
  }
}

-- Convert heading style name to level
pure func headingLevel(style: string) -> int = {
  if style == "Heading1" then 1
  else if style == "Heading2" then 2
  else if style == "Heading3" then 3
  else if style == "Heading4" then 4
  else if style == "Heading5" then 5
  else if style == "Heading6" then 6
  else 0
}

-- Check if style is a heading
pure func isHeading(style: string) -> bool = {
  headingLevel(style) > 0
}

-- Extract text from table cell
pure func getCellText(cellNode: XmlNode) -> string = {
  match findFirst(cellNode, "w:p") {
    Some(pNode) => getText(pNode),
    None => ""
  }
}

-- Convert a table row to list of TableCell
pure func parseTableRow(trNode: XmlNode) -> [TableCell] = {
  let cells = findAll(trNode, "w:tc");
  map(func(tcNode: XmlNode) -> TableCell {
    let cellText = getCellText(tcNode);
    simpleCell(cellText)
  }, cells)
}

-- Convert a table element to Block (treating first row as headers)
pure func parseTable(tblNode: XmlNode) -> Block = {
  let rows = findAll(tblNode, "w:tr");
  match rows {
    [] => mkTable([], []),
    headerRow :: dataRows => {
      let headers = parseTableRow(headerRow);
      let cellRows = map(parseTableRow, dataRows);
      TableBlock({rows: cellRows, headers: headers, caption: ""})
    }
  }
}

-- Process body elements and convert to blocks
pure func processBodyElements(body: XmlNode) -> [Block] = {
  let children = getChildren(body);
  processElements(children)
}

pure func processElements(elements: [XmlNode]) -> [Block] = {
  match elements {
    [] => [],
    elem :: rest => {
      let tag = getTag(elem);
      let block = if tag == "w:p" then {
        let style = getParagraphStyle(elem);
        let text = getText(elem);
        let isListItemBool = isListItem(elem);

        if isHeading(style) then
          HeadingBlock({text: text, level: headingLevel(style)})
        else if isListItemBool then
          ListBlock({items: [text], ordered: false})
        else
          TextBlock({text: text, style: style, level: 0})
      } else if tag == "w:tbl" then {
        parseTable(elem)
      } else {
        TextBlock({text: "", style: "", level: 0})
      };

      let restBlocks = processElements(rest);
      block :: restBlocks
    }
  }
}

export func parseDocx(filepath: string) -> [Block] ! {FS} {
  let content = readDocxContent(filepath);
  match parse(content) {
    Ok(doc) => {
      match findFirst(doc, "w:body") {
        Some(bodyNode) => processBodyElements(bodyNode),
        None => []
      }
    },
    Err(_) => []
  }
}

