from typing import TypeVar, Callable, Generic
from functools import wraps
from pathlib import Path


# Effect marker types
class IOEffect:
    """Marker class indicating a function has IO side effects."""
    pass


class FSEffect(IOEffect):
    """Marker class indicating a function has filesystem side effects (implies IO)."""
    pass


def io_effect(func: Callable) -> Callable:
    """Decorator to mark a function as having IO effects."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    wrapper.__effects__ = [IOEffect]
    return wrapper


def fs_effect(func: Callable) -> Callable:
    """Decorator to mark a function as having IO and filesystem effects."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    wrapper.__effects__ = [IOEffect, FSEffect]
    return wrapper


def computeSum(a: int | float, b: int | float) -> int | float:
    """PURE function: computes a + b with no side effects."""
    return a + b


@io_effect
def printSum(a: int | float, b: int | float) -> None:
    """IO effect: computes sum and prints it."""
    result = computeSum(a, b)
    print(f"Sum: {result}")


@fs_effect
def logToFile(filename: str, message: str) -> None:
    """IO + FS effect: writes message to a file."""
    path = Path(filename)
    with path.open("w", encoding="utf-8") as f:
        f.write(message + "\n")


def describe_effects(func: Callable) -> str:
    """Return a human-readable description of a function's effects."""
    effects = getattr(func, "__effects__", [])
    if not effects:
        return "PURE"
    names = [e.__name__ for e in effects]
    return ", ".join(names)


def main() -> None:
    # Demonstrate effect tracking metadata
    print(f"computeSum effects: {describe_effects(computeSum)}")
    print(f"printSum effects:   {describe_effects(printSum)}")
    print(f"logToFile effects:  {describe_effects(logToFile)}")
    print()

    # Call pure function
    result = computeSum(10, 20)
    _ = result  # stored but not printed directly (pure, no side effects)

    # Call IO function
    printSum(10, 20)

    # Call IO + FS function
    logToFile("output.txt", "Sum was 30")

    print("Done")


if __name__ == "__main__":
    main()

