module benchmark/solution

type Snapshot = { alice: int, bob: int }
type State = { alice: int, bob: int, stack: [Snapshot], failures: int }

type Op =
    Dep(string, int)
  | Wd(string, int)
  | Save
  | Commit
  | Restore

func step(s: State, op: Op) -> State =
  match op {
    Dep(acct, amt) =>
      if acct == "alice" then {s | alice: s.alice + amt}
      else {s | bob: s.bob + amt},
    Wd(acct, amt) =>
      let bal = if acct == "alice" then s.alice else s.bob in
      if bal >= amt then
        if acct == "alice" then {s | alice: s.alice - amt}
        else {s | bob: s.bob - amt}
      else
        let newFail = s.failures + 1 in
        match s.stack {
          [] => {s | failures: newFail},
          top :: rest => {s | alice: top.alice, bob: top.bob, stack: rest, failures: newFail}
        },
    Save =>
      let snap = {alice: s.alice, bob: s.bob} in
      {s | stack: snap :: s.stack},
    Commit =>
      match s.stack {
        [] => {s | failures: s.failures + 1},
        _ :: rest => {s | stack: rest}
      },
    Restore =>
      match s.stack {
        [] => {s | failures: s.failures + 1},
        top :: rest => {s | alice: top.alice, bob: top.bob, stack: rest}
      }
  }

func runOps(s: State, ops: [Op]) -> State =
  match ops {
    [] => s,
    op :: rest => runOps(step(s, op), rest)
  }

export func main() -> () ! {IO} {
  let initOps = [
    Save,
    Dep("alice", 30),
    Save,
    Wd("bob", 80),
    Wd("alice", 90),
    Save,
    Wd("alice", 50),
    Dep("bob", 25),
    Commit,
    Restore,
    Wd("bob", 75),
    Commit,
    Dep("alice", 5)
  ];
  let initState = { alice: 100, bob: 50, stack: [], failures: 0 };
  let finalState = runOps(initState, initOps);
  println("alice=${show(finalState.alice)}");
  println("bob=${show(finalState.bob)}");
  println("failures=${show(finalState.failures)}")
}

