from __future__ import annotations
from dataclasses import dataclass
from typing import Generic, TypeVar

T = TypeVar("T")


@dataclass
class Ok(Generic[T]):
    value: T


@dataclass
class Err:
    message: str


type Result[T] = Ok[T] | Err


def validate_age(age: int) -> Result[int]:
    if 0 <= age <= 150:
        return Ok(age)
    return Err("Age out of range")


def calculate_retirement_years(age: int) -> Result[int]:
    if age < 65:
        return Ok(65 - age)
    return Err("Already retired")


def chain_result(age: int) -> Result[int]:
    match validate_age(age):
        case Ok(value=valid_age):
            return calculate_retirement_years(valid_age)
        case Err() as err:
            return err


def format_result(result: Result[int]) -> str:
    match result:
        case Ok(value=years):
            return f"Years to retirement: {years}"
        case Err(message=msg):
            return f"Error: {msg}"


def main() -> None:
    test_ages = [30, 70, -5]
    for age in test_ages:
        result = chain_result(age)
        print(format_result(result))


if __name__ == "__main__":
    main()

