from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Num:
    value: int


@dataclass(frozen=True)
class Add:
    left: Expr
    right: Expr


@dataclass(frozen=True)
class Mul:
    left: Expr
    right: Expr


type Expr = Num | Add | Mul


def eval(expr: Expr) -> int:
    match expr:
        case Num(value):
            return value
        case Add(left, right):
            return eval(left) + eval(right)
        case Mul(left, right):
            return eval(left) * eval(right)
        case _:
            raise TypeError(f"Not an expression: {expr!r}")


def render(expr: Expr) -> str:
    match expr:
        case Num(value):
            return str(value)
        case Add(left, right):
            return f"({render(left)} + {render(right)})"
        case Mul(left, right):
            return f"{render(left)} * {render(right)}"
        case _:
            raise TypeError(f"Not an expression: {expr!r}")


def main() -> None:
    expr: Expr = Mul(Add(Num(3), Num(4)), Add(Num(2), Num(5)))
    print(f"{render(expr)} = {eval(expr)}")


