    def glob_match(pattern, string):
        # * never matches /
        # ? matches one char but never /
        # [abc] char class, [!...] negated, / only matched if listed

        def match(pi, si):
            # Returns True if pattern[pi:] matches string[si:]
            while pi < len(pattern):
                p = pattern[pi]
                if p == '*':
                    # * matches zero or more non-/ chars
                    # Try matching 0,1,2,... chars
                    # Use memoization via recursion with loop
                    # First try consuming 0 chars
                    if match(pi + 1, si):
                        return True
                    while si < len(string) and string[si] != '/':
                        si += 1
                        if match(pi + 1, si):
                            return True
                    return False
                elif p == '?':
                    if si >= len(string) or string[si] == '/':
                        return False
                    pi += 1
                    si += 1
                elif p == '[':
                    # find closing ]
                    pi += 1
                    negate = False
                    if pi < len(pattern) and pattern[pi] == '!':
                        negate = True
                        pi += 1
                    chars = set()
                    # parse char class
                    while pi < len(pattern) and pattern[pi] != ']':
                        if pi + 2 < len(pattern) and pattern[pi + 1] == '-' and pattern[pi + 2] != ']':
                            # range
                            lo = pattern[pi]
                            hi = pattern[pi + 2]
                            for c in range(ord(lo), ord(hi) + 1):
