                    ch = string[si]
                    in_set = ch in chars
                    if negate:
                        if in_set or ch == '/':
                            return False
                    else:
                        if not in_set:
                            return False
                        # if / is not in set, can't match /
                        # but we already checked in_set
                    si += 1
                else:
                    if si >= len(string) or string[si] != p:
                        return False
                    pi += 1
                    si += 1
            return si == len(string)

        return match(0, 0)

