                var_count[dest] += 1
                dest_ssa = f"{dest}.{idx}"
                current_def[dest] = dest_ssa
                ssa_instrs.append((dest_ssa, op, r1, r2))

    # Forward simplification
    # Table: SSA name -> Const(k), Copy(name), or Opaque
    table = {}  # SSA name -> ("const", val) or ("copy", name) or ("opaque",)

    def subst(operand):
        if operand is None:
            return None
        if isinstance(operand, int):
            return operand
        # It's an SSA name - follow chain
        visited = set()
        cur = operand
        while isinstance(cur, str):
            if cur in visited:
                break
            visited.add(cur)
            entry = table.get(cur)
            if entry is None:
                break
            if entry[0] == "const":
                return entry[1]
            elif entry[0] == "copy":
                cur = entry[1]
            else:
