            s1 = subst(op1)
            simplified.append(("return", None, s1, None))
            continue

        if op == "input":
            table[dest] = ("opaque",)
            kept.append(i)
            simplified.append(instr)
        elif op == "lit":
            table[dest] = ("const", op1)
            simplified.append(instr)
