def part8():
    # Count binary strings of length n with no "0110"
    # Use matrix exponentiation
    # States based on longest suffix matching prefix of "0110":
    # State 0: no partial match
    # State 1: matched "0"
    # State 2: matched "01"
    # State 3: matched "011"
    # State 4: matched "0110" -> forbidden (absorbing, not counted)
    # But we don't count strings that reach state 4
    # So states 0-3 are valid

    # Transitions for appending '0' or '1':
    # We use KMP failure function logic

    MOD = 1000000007
    pattern = "0110"

    # Build KMP automaton
    # States 0..3 (state 4 is fail state, absorbing)
    num_states = len(pattern)  # 4 valid states (0,1,2,3), state 4 = matched

    # Build transition table
    # fail function
    fail = [0] * (len(pattern) + 1)
    fail[0] = -1
    fail[1] = 0
    for i in range(2, len(pattern) + 1):
        j = fail[i - 1]
        while j >= 0 and pattern[j] != pattern[i - 1]:
            j = fail[j]
        fail[i] = j + 1

    def next_state(state, char):
        if state == len(pattern):  # absorbing
            return len(pattern)
        while state > 0 and pattern[state] != char:
            state = fail[state]
        if pattern[state] == char:
            state += 1
        return state

    # 4x4 matrix (states 0-3), state 4 is absorbing/forbidden
    size = 4  # only states 0-3

    def mat_mul(A, B):
        n = len(A)
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] == 0:
                    continue
                for j in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(M, p):
        n = len(M)
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        while p > 0:
            if p & 1:
                result = mat_mul(result, M)
            M = mat_mul(M, M)
            p >>= 1
        return result

    # Build transition matrix
    trans = [[0] * size for _ in range(size)]
    for state in range(size):
        for c in ['0', '1']:
            ns = next_state(state, c)
            if ns < size:  # not the forbidden state
                trans[state][ns] = (trans[state][ns] + 1) % MOD

    def count(n):
        if n == 0:
            return 1
        M = mat_pow(trans, n)
        # Start in state 0, count all valid end states
        total = 0
        for j in range(size):
            total = (total + M[0][j]) % MOD
        return total

    print(count(1000000000000000000))
    print(count(987654321987654321))


def part9():
    import string

    PUNCT = set('!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~')

    def is_ws(ch):
        return ch == ' ' or ch is None

    def is_punct(ch):
        return ch in PUNCT

    def parse_runs(text):
        # Returns list of (start, length, type) where type is 'star' or 'text'
        runs = []
        i = 0
        while i < len(text):
            if text[i] == '*':
                j = i
                while j < len(text) and text[j] == '*':
                    j += 1
                runs.append([i, j - i, 'star'])
                i = j
            else:
                j = i
                while j < len(text) and text[j] != '*':
                    j += 1
                runs.append([i, j - i, 'text'])
                i = j
        return runs

    def render(text):
        # Parse star runs and text runs
        tokens = parse_runs(text)

        # For each star run, determine left/right flanking
        star_runs = []  # [start, orig_len, remaining, can_open, can_close]

        for i, tok in enumerate(tokens):
            if tok[2] != 'star':
                continue
            start = tok[0]
            length = tok[1]

            # Previous char (before the run)
            prev_char = text[start - 1] if start > 0 else None
            # Next char (after the run)
            end = start + length
            next_char = text[end] if end < len(text) else None

            # Left flanking: next not ws AND (next not punct OR prev is ws/punct)
            left_flanking = (
                not is_ws(next_char) and
                (not is_punct(next_char) or is_ws(prev_char) or is_punct(prev_char))
            )
            # Right flanking: prev not ws AND (prev not punct OR next is ws/punct)
            right_flanking = (
                not is_ws(prev_char) and
                (not is_punct(prev_char) or is_ws(next_char) or is_punct(next_char))
            )

            can_open = left_flanking
            can_close = right_flanking

            star_runs.append([start, length, length, can_open, can_close])

        # Matching algorithm
        # Each entry: [start_in_text, orig_len, remaining, can_open, can_close]
        # We also need to track matches: list of (opener_idx, closer_idx, strength)

        runs = star_runs  # list of run entries
        matches = []  # (opener_run_idx, closer_run_idx, type: 'em' or 'strong')

        cursor = 0

        while cursor < len(runs):
            run = runs[cursor]
            if not run[4] or run[2] == 0:  # can't close or no stars
                cursor += 1
                continue

            # This is a closer - search backward for opener
            closer_idx = cursor
            opener_found = -1

            for j in range(closer_idx - 1, -1, -1):
                cand = runs[j]
                if not cand[3] or cand[2] == 0:  # can't open or no stars
                    continue

                # Rule of three check
                closer_also_opens = run[3]
                opener_also_closes = cand[4]
                if closer_also_opens or opener_also_closes:
                    orig_sum = run[1] + cand[1]
                    if orig_sum % 3 == 0:
                        if not (run[1] % 3 == 0 and cand[1] % 3 == 0):
                            continue

                opener_found = j
                break

            if opener_found == -1:
                if not run[3]:  # closer cannot open
                    # Remove from list (mark remaining as 0? No - keep literal)
                    # "remove it from the list"
                    runs.pop(cursor)
                    # cursor stays at this position (now pointing to next)
                else:
                    cursor += 1
