            # Match found
            opener = runs[opener_found]
            closer = run

            if opener[2] >= 2 and closer[2] >= 2:
                match_type = 'strong'
                consume = 2
            else:
                match_type = 'em'
                consume = 1

            opener[2] -= consume
            closer[2] -= consume

            matches.append((opener_found, closer_idx, match_type))

            # Remove runs strictly between opener and closer
            # Be careful about indices
            to_remove = list(range(opener_found + 1, closer_idx))
            for idx in reversed(to_remove):
                runs.pop(idx)

            # Adjust closer_idx after removal
            new_closer_idx = opener_found + 1

            # Remove opener/closer if remaining == 0
            removed_closer = False
            removed_opener = False

            if closer[2] == 0:
                runs.pop(new_closer_idx)
