            )

            orig_star_info.append([length, left_flanking, right_flanking])

        # Re-run matching algorithm with proper tracking
        # Each run entry: [original_star_run_index, orig_len, remaining, can_open, can_close]
        runs2 = []
        for si, info in enumerate(orig_star_info):
