        # - those that were consumed entirely in matches have remaining 0 (already in runs2 removed)
        # Actually let me handle: every orig star run has some remaining (could be 0)
        all_remaining = {}
        for si in range(len(orig_star_info)):
            all_remaining[si] = 0  # default: fully consumed
        for k, v in final_remaining.items():
