        # So at opener: we emit later match's open tag first (outermost), then earlier
        # At closer: we emit earlier match's close tag first, then later

        # Let's collect per run:
        opener_matches = defaultdict(list)  # orig_idx -> list of (match_index, type)
        closer_matches = defaultdict(list)  # orig_idx -> list of (match_index, type)

