def part10():
    def resolve(universe, app_pkg, app_ver):
        # universe: dict of (pkg, ver) -> list of (dep, lo, hi)
        # Start with assignment {app_pkg: app_ver}
        # Worklist: list of (dep, lo, hi)

        initial_reqs = universe.get((app_pkg, app_ver), [])

        def backtrack(assignment, worklist):
            if not worklist:
                return assignment

            req = worklist[0]
            rest = worklist[1:]
            dep, lo, hi = req

            if dep in assignment:
                v = assignment[dep]
                if lo <= v <= hi:
                    return backtrack(assignment, rest)
                else:
                    return None
            else:
                # Find all versions of dep in range, highest first
                candidates = []
                for (pkg, ver) in universe:
                    if pkg == dep and lo <= ver <= hi:
                        candidates.append(ver)
                candidates.sort(reverse=True)

                for ver in candidates:
                    new_assignment = dict(assignment)
                    new_assignment[dep] = ver
                    dep_reqs = universe.get((dep, ver), [])
                    new_worklist = dep_reqs + rest
                    result = backtrack(new_assignment, new_worklist)
                    if result is not None:
                        return result

                return None

        result = backtrack({app_pkg: app_ver}, initial_reqs)
        return result

    # Universe A
    univA = {
        ("app", 11): [("lib", 11, 13), ("util", 13, 13)],
        ("lib", 13): [("core", 13, 13)],
        ("lib", 12): [("core", 11, 12)],
        ("lib", 11): [],
        ("util", 13): [("core", 11, 11)],
        ("core", 13): [],
        ("core", 12): [],
        ("core", 11): [],
    }

    resultA = resolve(univA, "app", 11)
    if resultA is None:
        print("conflict")
    else:
        print("resolved")
        for name in sorted(resultA.keys()):
            print(f"{name}={resultA[name]}")

    # Universe B
    univB = {
        ("app", 11): [("x", 11, 11), ("y", 11, 11)],
        ("x", 11): [("core", 11, 11)],
        ("y", 11): [("core", 12, 12)],
        ("core", 12): [],
        ("core", 11): [],
    }

    resultB = resolve(univB, "app", 11)
    if resultB is None:
        print("conflict")
    else:
        print("resolved")
        for name in sorted(resultB.keys()):
            print(f"{name}={resultB[name]}")


