def gcd(a: int, b: int) -> int:
    """Computes the greatest common divisor using the Euclidean algorithm."""
    if b == 0:
        return a
    return gcd(b, a % b)

def lcm(a: int, b: int) -> int:
    """Computes the least common multiple using the formula."""
    if a == 0 or b == 0:
        return 0
    # Use integer division to return an integer result
    return abs(a * b) // gcd(a, b)

def main() -> None:
    val1 = 48
    val2 = 18

    print(gcd(val1, val2))
    print(lcm(val1, val2))

