module benchmark/solution

import std/io (println)
import std/string (chars)

type Tok = Star | Quest | Set(bool, [(string, string)]) | Lit(string)

pure func inRanges(c: string, rs: [(string, string)]) -> bool =
  match rs {
    [] => false,
    r :: rest =>
      match r {
        (lo, hi) => if lo <= c && c <= hi then true else inRanges(c, rest)
      }
  }

pure func parseSetBody(cs: [string]) -> ([(string, string)], [string]) =
  match cs {
    [] => ([], []),
    c :: rest =>
      if c == "]"
      then ([], rest)
      else
        match rest {
          [] => ([(c, c)], []),
          d :: rest2 =>
            if d == "-"
            then
              match rest2 {
                [] => ([(c, c)], []),
                hi :: rest3 =>
                  match parseSetBody(rest3) {
                    (rs, remaining) => ((c, hi) :: rs, remaining)
                  }
              }
            else
              match parseSetBody(rest) {
                (rs, remaining) => ((c, c) :: rs, remaining)
              }
        }
  }

pure func parseToks(cs: [string]) -> [Tok] =
  match cs {
    [] => [],
    c :: rest =>
      if c == "*"
      then Star :: parseToks(rest)
      else
        if c == "?"
        then Quest :: parseToks(rest)
        else
          if c == "["
          then
            match rest {
              [] => [],
              n :: rest2 =>
                if n == "!"
                then
                  match parseSetBody(rest2) {
                    (rs, remaining) => Set(true, rs) :: parseToks(remaining)
                  }
                else
                  match parseSetBody(rest) {
                    (rs, remaining) => Set(false, rs) :: parseToks(remaining)
                  }
            }
          else Lit(c) :: parseToks(rest)
  }

pure func matchToks(ts: [Tok], cs: [string]) -> bool =
  match ts {
    [] =>
      match cs {
        [] => true,
        _ => false
      },
    t :: rest =>
      match t {
        Star =>
          match cs {
            [] => matchToks(rest, []),
            c :: cr =>
              if c == "/"
              then matchToks(rest, cs)
              else matchToks(rest, cs) || matchToks(t :: rest, cr)
          },
        Quest =>
          match cs {
            [] => false,
            c :: cr => c != "/" && matchToks(rest, cr)
          },
        Lit(ch) =>
          match cs {
            [] => false,
            c :: cr => c == ch && matchToks(rest, cr)
          },
        Set(neg, rs) =>
          match cs {
            [] => false,
            c :: cr => {
              let inSet = inRanges(c, rs);
              let ok = if neg then c != "/" && not inSet else inSet;
              ok && matchToks(rest, cr)
            }
          }
      }
  }

pure func globMatch(pat: string, s: string) -> bool =
  matchToks(parseToks(chars(pat)), chars(s))

