def match(pattern: str, string: str) -> bool:
    return _match(pattern, 0, string, 0)


def _match(pattern: str, pi: int, string: str, si: int) -> bool:
    while pi < len(pattern):
        pc = pattern[pi]

        if pc == '*':
            # Skip consecutive stars
            while pi < len(pattern) and pattern[pi] == '*':
                pi += 1
            # If star is at end of pattern, string must have no '/'
            if pi == len(pattern):
                return '/' not in string[si:]
            # Try matching the rest of the pattern at each position in string
            # that doesn't involve crossing a '/'
            for i in range(si, len(string) + 1):
                if '/' in string[si:i]:
                    break
                if _match(pattern, pi, string, i):
                    return True
            return False

        elif pc == '?':
            if si >= len(string) or string[si] == '/':
                return False
            pi += 1
            si += 1

        elif pc == '[':
            # Find closing bracket
            end = pattern.index(']', pi + 1)
            set_content = pattern[pi + 1:end]
            negated = set_content.startswith('!')
            if negated:
                set_content = set_content[1:]

            if si >= len(string):
                return False

            ch = string[si]

            # Check if ch is in set
            in_set = _char_in_set(ch, set_content)

            # For [!...], never match '/'
            if negated:
                if ch == '/':
                    return False
                if in_set:
                    return False
            else:
                # For [...], '/' matches only if explicitly in set
                if ch == '/' and '/' not in set_content:
                    return False
                if not in_set:
                    return False

            pi = end + 1
            si += 1

        else:
            # Literal character
            if si >= len(string) or string[si] != pc:
                return False
            pi += 1
            si += 1

    return si == len(string)


def _char_in_set(ch: str, set_content: str) -> bool:
    i = 0
    while i < len(set_content):
        # Check for range: x-y
        if i + 2 < len(set_content) and set_content[i + 1] == '-':
            lo = set_content[i]
            hi = set_content[i + 2]
            if lo <= ch <= hi:
                return True
            i += 3
        else:
            if set_content[i] == ch:
                return True
            i += 1
    return False


def main():
    test_cases = [
        ("*.txt", "notes.txt"),
        ("*.txt", "dir/notes.txt"),
        ("a*b*c", "axbxbc"),
        ("a*b*c", "axbxbd"),
        ("?at", "cat"),
        ("?at", "/at"),
        ("[a-c]at", "bat"),
        ("[!a-c]at", "bat"),
        ("[!a-c]at", "rat"),
        ("[!/]x", "/x"),
        ("a[/]b", "a/b"),
        ("*", ""),
        ("*x*", "xx"),
        ("*ab", "aab"),
        ("a?c*", "abc"),
        ("*/", "abc/"),
    ]

    for pattern, string in test_cases:
        result = match(pattern, string)
        print(1 if result else 0)


if __name__ == "__main__":
    main()

