    y :: rest => if x == y then true else containsNode(x, rest)
  }

pure func getNeighbors(node: int, graph: [(int, [int])]) -> [int] =
  match graph {
    [] => [],
    pair :: rest => match pair {
      (n, neighbors) => if n == node then neighbors else getNeighbors(node, rest)
    }
  }

pure func processNeighbors(neighbors: [int], visited: [int], queue: [int]) -> ([int], [int]) =
  match neighbors {
    [] => (visited, queue),
    n :: rest =>
      if containsNode(n, visited) then
        processNeighbors(rest, visited, queue)
      else
        processNeighbors(rest, visited ++ [n], queue ++ [n])
  }

pure func bfsLoop(queue: [int], visited: [int], acc: [int], graph: [(int, [int])]) -> [int] =
  match queue {
    [] => acc,
    curr :: qRest =>
      let neighbors = getNeighbors(curr, graph) in
      match processNeighbors(neighbors, visited, qRest) {
        (nextVisited, nextQueue) => bfsLoop(nextQueue, nextVisited, acc ++ [curr], graph)
      }
  }

pure func bfs(start: int, graph: [(int, [int])]) -> [int] =
