def contains(x, lst):
    return x in lst


def enqueue(x, queue):
    queue.append(x)


def get_neighbors(node, graph):
    for n, neighbors in graph:
        if n == node:
            return neighbors
    return []


def bfs(graph, start):
    visited = []
    queue = []

    enqueue(start, queue)

    while queue:
        current = queue.pop(0)

        if not contains(current, visited):
            visited.append(current)

            neighbors = get_neighbors(current, graph)
            for neighbor in neighbors:
                if not contains(neighbor, visited):
                    enqueue(neighbor, queue)

    return visited


