from typing import Optional


def median(xs: list[int]) -> Optional[int]:
    """Return the median of `xs`, choosing the lower middle value when the
    length is even. Returns None for an empty (or unusable) input instead of
    raising, keeping the function total."""
    try:
        values = sorted(xs)
    except TypeError:
        return None
    if not values:
        return None
    return values[(len(values) - 1) // 2]


def main() -> None:
    print(median([7, 2, 5, 1, 9, 4, 8]))
    print(median([10, 20, 30, 40]))


