module benchmark/solution

type Term = TVar(string) | TLam(string, Term) | TApp(Term, Term)

pure func subst(term: Term, name: string, replacement: Term) -> Term {
  match term {
    TVar(x) => if x == name then replacement else TVar(x),
    TLam(x, body) => if x == name then TLam(x, body) else TLam(x, subst(body, name, replacement)),
    TApp(f, a) => TApp(subst(f, name, replacement), subst(a, name, replacement))
  }
}

pure func eval(term: Term) -> Term {
  match term {
    TVar(x) => TVar(x),
    TLam(x, body) => TLam(x, body),
    TApp(f, a) => {
      let fv = eval(f);
      let av = eval(a);
      match fv {
        TLam(x, body) => eval(subst(body, x, av)),
        _ => TApp(fv, av)
      }
    }
  }
}

pure func termToString(term: Term) -> string {
  match term {
    TVar(x) => x,
    TLam(x, body) => "λ${x}.${termToString(body)}",
    TApp(f, a) => "(${termToString(f)} ${termToString(a)})"
  }
}

export func main() -> () ! {IO} {
  let expr = TApp(TApp(TLam("x", TLam("y", TVar("x"))), TVar("1")), TVar("2"));
  println(termToString(eval(expr)))
