from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class TVar:
    name: str

    def __repr__(self) -> str:
        return f'TVar("{self.name}")'

    def __str__(self) -> str:
        return self.name

@dataclass(frozen=True)
class TLam:
    var: str
    body: Term

    def __repr__(self) -> str:
        return f'TLam("{self.var}", {self.body!r})'

    def __str__(self) -> str:
        return f"(λ{self.var}.{self.body})"

@dataclass(frozen=True)
class TApp:
    func: Term
    arg: Term

    def __repr__(self) -> str:
        return f'TApp({self.func!r}, {self.arg!r})'

    def __str__(self) -> str:
        return f"({self.func} {self.arg})"

type Term = TVar | TLam | TApp

def subst(term: Term, var: str, replacement: Term) -> Term:
    """Substitute var with replacement in term."""
    match term:
        case TVar(name):
            return replacement if name == var else term
        case TLam(name, body):
            # If the lambda parameter shadows the target variable, no substitution happens in the body
            if name == var:
                return term
            return TLam(name, subst(body, var, replacement))
        case TApp(f, a):
            return TApp(subst(f, var, replacement), subst(a, var, replacement))

def eval_term(term: Term) -> Term:
    """Evaluate term using call-by-value strategy."""
    match term:
        case TVar(_):
            # Variables evaluate to themselves
            return term
        case TLam(_, _):
            # Lambdas are values
            return term
        case TApp(f, a):
            # Evaluate function and argument
            f_val = eval_term(f)
            a_val = eval_term(a)
            # If the evaluated function is a lambda, substitute and evaluate the result
            if isinstance(f_val, TLam):
                return eval_term(subst(f_val.body, f_val.var, a_val))
            # Otherwise, return the application of evaluated parts
            return TApp(f_val, a_val)

def main() -> None:
    # Evaluate: (λx. λy. x) 1 2
    # This is the K combinator applied to 1 then to 2.
    # The result should be "1".

    # AST: TApp(TApp(TLam("x", TLam("y", TVar("x"))), TVar("1")), TVar("2"))
    k_combinator = TLam("x", TLam("y", TVar("x")))
    expr = TApp(
        TApp(k_combinator, TVar("1")),
        TVar("2")
    )

    result = eval_term(expr)

    # Printing the result. For TVar("1"), this will print "1".
    # Using repr() would show TVar("1").
    print(result)

if __name__ == "__main__":
    main()

