module benchmark/solution

import std/io (println)
import std/option (Option, Some, None)
import std/list (map)

type BreachKind = DelivBreach | PayBreach deriving (Eq)

type Milestone = {
  id: string,
  deadline: int,
  price: int,
  delivered_day: Option[int],
  paid_day: Option[int],
  cancelled: bool
}

type BreachNotice = {
  milestone_id: string,
  breach_type: BreachKind,
  notice_day: int
}

type Waiver = {
  milestone_id: string,
  breach_type: BreachKind
}

type Termination = {
  day: int,
  by: string,
  grounds: string
}

type State = {
  milestones: [Milestone],
  notices: [BreachNotice],
  waivers: [Waiver],
  termination: Option[Termination]
}

type Event =
    EvDelivery(int, string)
  | EvAmendment(int, string, int)
  | EvForceMajeure(int, int, int)
  | EvPayment(int, string)
  | EvWaiver(int, string, BreachKind)
  | EvNotice(int, string, BreachKind)
  | EvTerminate(int, string)

func isWaived(m_id: string, kind: BreachKind, waivers: [Waiver]) -> bool =
  match waivers {
    [] => false,
    w :: rest => if w.milestone_id == m_id && w.breach_type == kind then true else isWaived(m_id, kind, rest)
  }

func getNotice(m_id: string, kind: BreachKind, notices: [BreachNotice]) -> Option[BreachNotice] =
  match notices {
    [] => None,
    n :: rest => if n.milestone_id == m_id && n.breach_type == kind then Some(n) else getNotice(m_id, kind, rest)
  }

func findMilestone(id: string, ms: [Milestone]) -> Option[Milestone] =
  match ms {
    [] => None,
    m :: rest => if m.id == id then Some(m) else findMilestone(id, rest)
  }

func isCured(notice: BreachNotice, ms: [Milestone]) -> bool =
  match findMilestone(notice.milestone_id, ms) {
    None => false,
    Some(m) => match notice.breach_type {
      DelivBreach => match m.delivered_day {
        Some(d) => d <= notice.notice_day + 15,
        None => false
      },
      PayBreach => match m.paid_day {
        Some(d) => d <= notice.notice_day + 15,
        None => false
      }
    }
  }

func findGrounds(day: int, notices: [BreachNotice], waivers: [Waiver], ms: [Milestone]) -> Option[string] =
  match notices {
    [] => None,
    n :: rest => {
      let waived = isWaived(n.milestone_id, n.breach_type, waivers);
      let cured = isCured(n, ms);
      let expired = day > n.notice_day + 15;
      if (not waived) && (not cured) && expired then {
        let kind_str = match n.breach_type {
          DelivBreach => "delivery",
          PayBreach => "payment"
        };
        Some("${n.milestone_id}-${kind_str}")
      } else {
        findGrounds(day, rest, waivers, ms)
      }
    }
  }

func processEvent(event: Event, state: State) -> State =
  match event {
    EvDelivery(day, m_id) => {
      let new_ms = map(func(m: Milestone) -> Milestone {
        if m.id == m_id then { m | delivered_day: Some(day) } else m
      }, state.milestones);
      { state | milestones: new_ms }
    },
    EvAmendment(day, m_id, new_price) => {
      let new_ms = map(func(m: Milestone) -> Milestone {
        if m.id == m_id then { m | price: new_price } else m
      }, state.milestones);
      { state | milestones: new_ms }
    },
    EvForceMajeure(day, d1, d2) => {
      let w_len = d2 - d1 + 1;
      let new_ms = map(func(m: Milestone) -> Milestone {
        match m.delivered_day {
          Some(_) => m,
          None => if m.deadline >= d1 && m.deadline <= d2 then { m | deadline: m.deadline + w_len } else m
        }
      }, state.milestones);
      { state | milestones: new_ms }
    },
    EvPayment(day, m_id) => {
      let new_ms = map(func(m: Milestone) -> Milestone {
        if m.id == m_id then { m | paid_day: Some(day) } else m
      }, state.milestones);
      { state | milestones: new_ms }
    },
    EvWaiver(day, m_id, kind) => {
      let new_w = state.waivers ++ [{ milestone_id: m_id, breach_type: kind }];
      { state | waivers: new_w }
    },
    EvNotice(day, m_id, kind) => {
      let new_n = state.notices ++ [{ milestone_id: m_id, breach_type: kind, notice_day: day }];
      { state | notices: new_n }
    },
    EvTerminate(day, by_party) => {
      match state.termination {
        Some(_) => state,
        None => {
          match findGrounds(day, state.notices, state.waivers, state.milestones) {
            None => state,
            Some(g) => {
              let term = { day: day, by: by_party, grounds: g };
              let new_ms = map(func(m: Milestone) -> Milestone {
                match m.delivered_day {
                  Some(_) => m,
                  None => { m | cancelled: true }
                }
              }, state.milestones);
              { state | milestones: new_ms, termination: Some(term) }
            }
          }
        }
      }
    }
  }

func processEvents(events: [Event], state: State) -> State =
  match events {
    [] => state,
    ev :: rest => processEvents(rest, processEvent(ev, state))
  }

func getDeliveryPenalty(m: Milestone, state: State) -> int =
  match m.delivered_day {
    Some(d) => {
      let late = if d > m.deadline then d - m.deadline else 0;
      let p = late * 200;
      if p > 4000 then 4000 else p
    },
    None => match state.termination {
      Some(term) => {
        let late = if term.day - 1 > m.deadline then (term.day - 1) - m.deadline else 0;
        let p = late * 200;
        if p > 4000 then 4000 else p
      },
      None => 0
    }
  }

func getPaymentInterest(m: Milestone) -> int =
  match m.paid_day {
    Some(pd) => match m.delivered_day {
      Some(dd) => {
        let due = dd + 10;
        let late = if pd > due then pd - due else 0;
        m.price * (late / 10) / 100
      },
      None => 0
    },
    None => 0
  }

func printEffective(ms: [Milestone]) -> () ! {IO} =
  match ms {
    [] => (),
    m :: rest => {
      println("${m.id} effective: deadline=${show(m.deadline)} price=${show(m.price)}");
      printEffective(rest)
    }
  }

func printMilestoneBlock(m: Milestone, state: State) -> () ! {IO} {
  match m.delivered_day {
    Some(d) => {
      let late = if d > m.deadline then d - m.deadline else 0;
      let raw_p = late * 200;
      let penalty = if raw_p > 4000 then 4000 else raw_p;
      println("${m.id} delivery: DELIVERED day=${show(d)} late=${show(late)} penalty=${show(penalty)}")
    },
    None => match state.termination {
      Some(term) => {
        let late = if term.day - 1 > m.deadline then (term.day - 1) - m.deadline else 0;
        let raw_p = late * 200;
        let penalty = if raw_p > 4000 then 4000 else raw_p;
        println("${m.id} delivery: CANCELLED late_days=${show(late)} penalty=${show(penalty)}")
      },
      None => ()
    }
  };

  match m.paid_day {
    Some(pd) => match m.delivered_day {
      Some(dd) => {
        let due = dd + 10;
        let late = if pd > due then pd - due else 0;
        let interest = m.price * (late / 10) / 100;
        println("${m.id} payment: PAID day=${show(pd)} late=${show(late)} interest=${show(interest)}")
      },
      None => println("${m.id} payment: CANCELLED")
    },
    None => println("${m.id} payment: CANCELLED")
  };

  let deliv_w = isWaived(m.id, DelivBreach, state.waivers);
  let deliv_n = getNotice(m.id, DelivBreach, state.notices);
  match deliv_n {
    Some(n) => {
      let status = if deliv_w then "WAIVED" else if isCured(n, state.milestones) then "CURED" else "UNCURED";
      println("${m.id} delivery breach: ${status}")
    },
    None => if deliv_w then {
      println("${m.id} delivery breach: WAIVED")
    } else ()
  };

  let pay_w = isWaived(m.id, PayBreach, state.waivers);
  let pay_n = getNotice(m.id, PayBreach, state.notices);
  match pay_n {
    Some(n) => {
      let status = if pay_w then "WAIVED" else if isCured(n, state.milestones) then "CURED" else "UNCURED";
      println("${m.id} payment breach: ${status}")
    },
    None => if pay_w then {
      println("${m.id} payment breach: WAIVED")
    } else ()
  }
}

func printBlocks(ms: [Milestone], state: State) -> () ! {IO} =
  match ms {
    [] => (),
    m :: rest => {
      printMilestoneBlock(m, state);
      printBlocks(rest, state)
    }
  }

func sumVendorOwes(ms: [Milestone], state: State) -> int =
  match ms {
    [] => 0,
    m :: rest => {
      let waived = isWaived(m.id, DelivBreach, state.waivers);
      let penalty = if waived then 0 else getDeliveryPenalty(m, state);
      penalty + sumVendorOwes(rest, state)
    }
  }

func sumClientOwes(ms: [Milestone], state: State) -> int =
  match ms {
    [] => 0,
    m :: rest => {
      let waived = isWaived(m.id, PayBreach, state.waivers);
      let interest = if waived then 0 else getPaymentInterest(m);
      interest + sumClientOwes(rest, state)
    }
  }

export func main() -> () ! {IO} {
  let initial_milestones = [
    { id: "M1", deadline: 10, price: 10000, delivered_day: None, paid_day: None, cancelled: false },
    { id: "M2", deadline: 40, price: 20000, delivered_day: None, paid_day: None, cancelled: false },
    { id: "M3", deadline: 70, price: 15000, delivered_day: None, paid_day: None, cancelled: false }
  ];

  let initial_state = {
    milestones: initial_milestones,
    notices: [],
    waivers: [],
    termination: None
  };

  let events = [
    EvDelivery(8, "M1"),
    EvAmendment(30, "M2", 22000),
    EvForceMajeure(35, 38, 44),
    EvPayment(41, "M1"),
    EvWaiver(45, "M1", PayBreach),
    EvDelivery(50, "M2"),
    EvNotice(61, "M2", PayBreach),
    EvPayment(74, "M2"),
    EvNotice(80, "M3", DelivBreach),
    EvTerminate(96, "Client")
  ];

  let final_state = processEvents(events, initial_state);

  printEffective(final_state.milestones);
  printBlocks(final_state.milestones, final_state);

  match final_state.termination {
    Some(term) => println("termination: day=${show(term.day)} by=${term.by} grounds=${term.grounds}"),
    None => ()
  };

  let v_owes = sumVendorOwes(final_state.milestones, final_state);
  let c_owes = sumClientOwes(final_state.milestones, final_state);

  println("vendor_owes=${show(v_owes)}");
  println("client_owes=${show(c_owes)}");

  if v_owes > c_owes then {
    println("net: Vendor pays Client ${show(v_owes - c_owes)}")
  } else if c_owes > v_owes then {
    println("net: Client pays Vendor ${show(c_owes - v_owes)}")
  } else {
    println("net: settled")
  }
}

