from __future__ import annotations

from dataclasses import dataclass, field

PENALTY_PER_DAY = 200
PENALTY_CAP = 4000
CURE_DAYS = 15
PAYMENT_TERM_DAYS = 10


@dataclass
class Milestone:
    name: str
    deadline: int
    price: int
    delivered_day: int | None = None
    delivery_late: int = 0
    penalty: int = 0
    delivery_cancelled: bool = False
    payment_due: int | None = None
    paid_day: int | None = None
    payment_late: int = 0
    interest: int = 0
    payment_cancelled: bool = False


@dataclass
class Breach:
    ident: str
    milestone: str
    kind: str  # "delivery" or "payment"
    notice_day: int | None = None
    waived: bool = False


@dataclass
class Contract:
    milestones: dict[str, Milestone]
    breaches: dict[str, Breach] = field(default_factory=dict)
    notice_order: list[str] = field(default_factory=list)
    terminated_day: int | None = None
    termination_grounds: str | None = None

    # --- helpers -----------------------------------------------------
    def breach(self, ident: str) -> Breach:
        if ident not in self.breaches:
            name, kind = ident.split("-")
            self.breaches[ident] = Breach(ident, name, kind)
        return self.breaches[ident]

    def is_cured(self, br: Breach) -> bool:
        if br.notice_day is None:
            return False
        limit = br.notice_day + CURE_DAYS
        m = self.milestones[br.milestone]
        if br.kind == "delivery":
            return m.delivered_day is not None and m.delivered_day <= limit
        return m.paid_day is not None and m.paid_day <= limit

    # --- event handlers ----------------------------------------------
    def deliver(self, day: int, name: str) -> None:
        m = self.milestones[name]
        m.delivered_day = day
        m.delivery_late = max(0, day - m.deadline)
        m.penalty = min(m.delivery_late * PENALTY_PER_DAY, PENALTY_CAP)
        m.payment_due = day + PAYMENT_TERM_DAYS

    def amend(self, day: int, name: str, price: int) -> None:
        self.milestones[name].price = price

    def force_majeure(self, day: int, start: int, end: int) -> None:
        length = end - start + 1
        for m in self.milestones.values():
            if m.delivered_day is None and start <= m.deadline <= end:
                m.deadline += length

    def pay(self, day: int, name: str) -> None:
        m = self.milestones[name]
        m.paid_day = day
        due = m.payment_due if m.payment_due is not None else m.deadline + PAYMENT_TERM_DAYS
        m.payment_late = max(0, day - due)
        m.interest = m.price * (m.payment_late // 10) // 100

    def notice(self, day: int, ident: str) -> None:
        br = self.breach(ident)
        br.notice_day = day
        if ident not in self.notice_order:
            self.notice_order.append(ident)

    def waive(self, day: int, ident: str) -> None:
        self.breach(ident).waived = True

    def terminate(self, day: int) -> None:
        grounds = None
        for ident in self.notice_order:
            br = self.breaches[ident]
            if br.waived or self.is_cured(br):
                continue
            if br.notice_day is not None and day > br.notice_day + CURE_DAYS:
                grounds = ident
                break
        if grounds is None:
            return
        self.terminated_day = day
        self.termination_grounds = grounds
        for m in self.milestones.values():
            if m.delivered_day is None:
                m.delivery_cancelled = True
                late = max(0, (day - 1) - m.deadline)
                m.delivery_late = late
                m.penalty = min(late * PENALTY_PER_DAY, PENALTY_CAP)
                m.payment_cancelled = True
            elif m.paid_day is None:
                m.payment_cancelled = True


def build() -> tuple[Contract, list[tuple]]:
    contract = Contract(
        milestones={
            "M1": Milestone("M1", 10, 10000),
            "M2": Milestone("M2", 40, 20000),
            "M3": Milestone("M3", 70, 15000),
        }
    )
    events: list[tuple] = [
        (8, "deliver", {"name": "M1"}),
        (30, "amend", {"name": "M2", "price": 22000}),
        (35, "force_majeure", {"start": 38, "end": 44}),
        (41, "pay", {"name": "M1"}),
        (45, "waive", {"ident": "M1-payment"}),
        (50, "deliver", {"name": "M2"}),
        (61, "notice", {"ident": "M2-payment"}),
        (74, "pay", {"name": "M2"}),
        (80, "notice", {"ident": "M3-delivery"}),
        (96, "terminate", {}),
    ]
    return contract, events


def process(contract: Contract, events: list[tuple]) -> None:
    for day, kind, kwargs in sorted(events, key=lambda e: e[0]):
        handler = getattr(contract, kind)
        handler(day, **kwargs)


def report(contract: Contract) -> list[str]:
    lines: list[str] = []
    order = ["M1", "M2", "M3"]

    for name in order:
        m = contract.milestones[name]
        lines.append(f"{name} effective: deadline={m.deadline} price={m.price}")

    for name in order:
        m = contract.milestones[name]
        if m.delivery_cancelled:
            lines.append(
                f"{name} delivery: CANCELLED late_days={m.delivery_late} "
                f"penalty={m.penalty}"
            )
        else:
            lines.append(
                f"{name} delivery: DELIVERED day={m.delivered_day} "
                f"late={m.delivery_late} penalty={m.penalty}"
            )
        if m.payment_cancelled:
            lines.append(f"{name} payment: CANCELLED")
        else:
            lines.append(
                f"{name} payment: PAID day={m.paid_day} "
                f"late={m.payment_late} interest={m.interest}"
            )
        for kind in ("delivery", "payment"):
            br = contract.breaches.get(f"{name}-{kind}")
            if br is None or (br.notice_day is None and not br.waived):
                continue
            if br.waived:
                status = "WAIVED"
            elif contract.is_cured(br):
                status = "CURED"
            else:
                status = "UNCURED"
            lines.append(f"{name} {kind} breach: {status}")

    if contract.terminated_day is not None:
        lines.append(
            f"termination: day={contract.terminated_day} by=Client "
            f"grounds={contract.termination_grounds}"
        )
    else:
        lines.append("termination: none")

    def waived(name: str, kind: str) -> bool:
        br = contract.breaches.get(f"{name}-{kind}")
        return br is not None and br.waived

    vendor_owes = sum(
        m.penalty for m in contract.milestones.values() if not waived(m.name, "delivery")
    )
    client_owes = sum(
        m.interest for m in contract.milestones.values() if not waived(m.name, "payment")
    )
    lines.append(f"vendor_owes={vendor_owes}")
    lines.append(f"client_owes={client_owes}")

    if vendor_owes > client_owes:
        lines.append(f"net: Vendor pays Client {vendor_owes - client_owes}")
    elif client_owes > vendor_owes:
        lines.append(f"net: Client pays Vendor {client_owes - vendor_owes}")
    else:
        lines.append("net: settled")
    return lines


def main() -> None:
    contract, events = build()
    process(contract, events)
    print("\n".join(report(contract)))


if __name__ == "__main__":
    main()

