module benchmark/solution

import std/option (Option, Some, None)

type Entry = { key: int, val: int, count: int, last_used: int }
type Op = Get(int) | Put(int, int)

func is_less(a: Entry, b: Entry) -> bool =
  if a.count < b.count then true
  else if a.count > b.count then false
  else a.last_used < b.last_used

func exists_key(cache: [Entry], k: int) -> bool =
  match cache {
    [] => false,
    e :: rest => if e.key == k then true else exists_key(rest, k)
  }

func get_entry(cache: [Entry], k: int) -> Option[Entry] =
  match cache {
    [] => None,
    e :: rest => if e.key == k then Some(e) else get_entry(rest, k)
  }

func update_entry(cache: [Entry], k: int, newVal: Option[int], t: int) -> [Entry] =
  match cache {
    [] => [],
    e :: rest =>
      if e.key == k then
        let v = match newVal { Some(v0) => v0, None => e.val } in
        { key: e.key, val: v, count: e.count + 1, last_used: t } :: rest
      else
        e :: update_entry(rest, k, newVal, t)
  }

func find_victim(cache: [Entry]) -> Option[Entry] =
  match cache {
    [] => None,
    e :: rest =>
      match find_victim(rest) {
        None => Some(e),
        Some(v) => if is_less(e, v) then Some(e) else Some(v)
      }
  }

func remove_key(cache: [Entry], k: int) -> [Entry] =
  match cache {
    [] => [],
    e :: rest => if e.key == k then rest else e :: remove_key(rest, k)
  }

func evict(cache: [Entry]) -> [Entry] =
  match find_victim(cache) {
    None => cache,
    Some(v) => remove_key(cache, v.key)
  }

func cache_len(cache: [Entry]) -> int =
  match cache {
    [] => 0,
    _ :: rest => 1 + cache_len(rest)
  }

func handle_put(cache: [Entry], k: int, v: int, t: int) -> [Entry] =
  if exists_key(cache, k) then
    update_entry(cache, k, Some(v), t)
  else
    let c1 = if cache_len(cache) >= 3 then evict(cache) else cache in
    { key: k, val: v, count: 1, last_used: t } :: c1

func process_ops(ops: [Op], cache: [Entry], t: int) -> [Entry] ! {IO} {
  match ops {
    [] => cache,
    op :: rest =>
      match op {
        Get(k) =>
          match get_entry(cache, k) {
            Some(e) => {
              println(show(e.val));
              let new_cache = update_entry(cache, k, None, t);
              process_ops(rest, new_cache, t + 1)
            },
            None => {
              println("-1");
              process_ops(rest, cache, t + 1)
            }
          },
        Put(k, v) => {
          let new_cache = handle_put(cache, k, v, t);
          process_ops(rest, new_cache, t + 1)
        }
      }
  }
}

func insert_sorted(e: Entry, xs: [Entry]) -> [Entry] =
  match xs {
    [] => [e],
    y :: ys => if e.key <= y.key then e :: y :: ys else y :: insert_sorted(e, ys)
  }

func sort_cache(xs: [Entry]) -> [Entry] =
  match xs {
    [] => [],
    y :: ys => insert_sorted(y, sort_cache(ys))
  }

func format_entries(xs: [Entry]) -> string =
  match xs {
    [] => "",
    e :: [] => "${show(e.key)}=${show(e.val)}",
    e :: rest => "${show(e.key)}=${show(e.val)},${format_entries(rest)}"
  }

func print_final_cache(cache: [Entry]) -> () ! {IO} {
  let sorted = sort_cache(cache);
  let formatted = format_entries(sorted);
  println("cache: ${formatted}")
}

export func main() -> () ! {IO} {
  let ops = [
    Put(1, 10),
    Put(2, 20),
    Put(3, 30),
    Get(1),
    Put(4, 40),
    Put(5, 50),
    Get(3),
    Get(4),
    Get(5),
    Get(1),
    Put(4, 44),
    Put(6, 60),
    Get(5),
    Get(6),
    Get(6),
    Put(7, 70),
    Get(1),
    Get(4),
    Put(8, 80),
    Get(7)
  ];
  let final_cache = process_ops(ops, [], 1);
  print_final_cache(final_cache)
}

