module benchmark/solution

import std/io (println)
import std/fs (writeFile, readFile)
import std/string (split, contains, join, compare)
import std/list (filter, length, nth, last, sortBy, dedup)
import std/option (Some, None)

type Stats = { info: int, error: int, warning: int, users: [string] }

func processLines(lines: [string], acc: Stats) -> Stats =
  match lines {
    [] => acc,
    line :: rest => {
      let parts = split(line, " ");
      let level = match nth(parts, 2) {
        Some(l) => l,
        None => ""
      };
      let newUsers = if contains(line, "User logged") then
        match last(parts) {
          Some(u) => u :: acc.users,
          None => acc.users
        }
      else acc.users;
      let newAcc = {
        info: if level == "INFO" then acc.info + 1 else acc.info,
        error: if level == "ERROR" then acc.error + 1 else acc.error,
        warning: if level == "WARNING" then acc.warning + 1 else acc.warning,
        users: newUsers
      };
      processLines(rest, newAcc)
    }
  }

export func main() -> () ! {IO, FS} {
  let logData = "2024-10-29 10:00:00 INFO User logged in: alice\n2024-10-29 10:01:15 ERROR Database connection failed\n2024-10-29 10:02:30 INFO User logged in: bob\n2024-10-29 10:03:45 WARNING High memory usage: 85%\n2024-10-29 10:05:00 ERROR API timeout: /users endpoint\n2024-10-29 10:06:15 INFO User logged out: alice";
  writeFile("app.log", logData);
  let content = readFile("app.log");
  let rawLines = split(content, "\n");
  let validLines = filter(\s. s != "", rawLines);
  let total = length(validLines);
  let initStats = { info: 0, error: 0, warning: 0, users: [] };
  let stats = processLines(validLines, initStats);
  let infoPct = stats.info * 100 / total;
  let errorPct = stats.error * 100 / total;
  let warningPct = stats.warning * 100 / total;
  let sortedUsers = sortBy(compare, stats.users);
  let uniqueUsers = dedup(sortedUsers);
  let userStr = join(", ", uniqueUsers);
  println("Total log entries: ${show(total)}");
  println("INFO: ${show(stats.info)} (${show(infoPct)}%)");
  println("ERROR: ${show(stats.error)} (${show(errorPct)}%)");
  println("WARNING: ${show(stats.warning)} (${show(warningPct)}%)");
  println("Unique users: ${userStr}")
}

