module benchmark/solution

import std/io (println)

func merge(xs: [int], ys: [int]) -> [int] =
  match xs {
    [] => ys,
    x :: xrest => match ys {
      [] => xs,
      y :: yrest =>
        if x <= y then x :: merge(xrest, ys)
        else y :: merge(xs, yrest)
    }
