from __future__ import annotations
from dataclasses import dataclass
from typing import Union


@dataclass
class Num:
    value: int


@dataclass
class Var:
    name: str


@dataclass
class Add:
    left: Expr
    right: Expr


@dataclass
class Mul:
    left: Expr
    right: Expr


@dataclass
class Let:
    name: str
    binding: Expr
    body: Expr


Expr = Union[Num, Var, Add, Mul, Let]
Env = list[tuple[str, int]]


def lookup(name: str, env: Env) -> int:
    for var_name, value in reversed(env):
        if var_name == name:
            return value
    raise NameError(f"Variable '{name}' not found in environment")


def eval(expr: Expr, env: Env) -> int:
    match expr:
        case Num(value=v):
            return v
        case Var(name=n):
            return lookup(n, env)
        case Add(left=l, right=r):
            return eval(l, env) + eval(r, env)
        case Mul(left=l, right=r):
            return eval(l, env) * eval(r, env)
        case Let(name=n, binding=e1, body=e2):
            val = eval(e1, env)
            new_env = env + [(n, val)]
            return eval(e2, new_env)
        case _:
            raise ValueError(f"Unknown expression type: {expr}")


def main() -> None:
    program = Let(
        "x",
        Num(5),
        Let(
            "y",
            Add(Var("x"), Num(3)),
            Mul(Var("x"), Var("y"))
        )
    )

    env: Env = []
    result = eval(program, env)
    print(result)


if __name__ == "__main__":
