from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Generic, TypeVar

T = TypeVar("T")
U = TypeVar("U")


@dataclass(frozen=True)
class Some(Generic[T]):
    value: T


def safeLast(items: list[T]) -> Some[T] | None:
    return Some(items[-1]) if items else None


def safeHead(items: list[T]) -> Some[T] | None:
    return Some(items[0]) if items else None


def flatMapOption(fn: Callable[[T], Some[U] | None], option: Some[T] | None) -> Some[U] | None:
    if option is None:
        return None
    return fn(option.value)


def main() -> None:
    fruits = ["apple", "banana", "cherry"]
    last = safeLast(fruits)
    last_with_head = flatMapOption(lambda s: safeHead(list(s)), last)

    if last_with_head is not None:
        print(f"Last starts with: {last_with_head.value}")

    empty_fruits: list[str] = []
    empty_last = safeLast(empty_fruits)
    empty_result = flatMapOption(lambda s: safeHead(list(s)), empty_last)

    if empty_result is None:
        print("Empty list")


