func isDigit(c: string) -> bool =
  c == "0" || c == "1" || c == "2" || c == "3" || c == "4" ||
  c == "5" || c == "6" || c == "7" || c == "8" || c == "9"

func readNum(acc: string, cs: [string]) -> (string, [string]) =
  match cs {
    [] => (acc, []),
    c :: rest =>
      if isDigit(c) then readNum("${acc}${c}", rest)
      else (acc, cs)
  }

func tokenize(cs: [string]) -> [string] =
  match cs {
    [] => [],
    c :: rest =>
      if isDigit(c) then match readNum(c, rest) {
        (numStr, remainingCs) => numStr :: tokenize(remainingCs)
      }
      else c :: tokenize(rest)
  }

func parsePrimary(tokens: [string]) -> (string, [string]) =
  match tokens {
    "(" :: rest => match parseAddSub(rest) {
      (expr, rest2) => match rest2 {
        ")" :: rest3 => (expr, rest3),
        _ => (expr, rest2)
      }
    },
    tok :: rest => (tok, rest),
    [] => ("", [])
  }

func parsePower(tokens: [string]) -> (string, [string]) =
  match parsePrimary(tokens) {
    (base, rest) => match rest {
      "^" :: rest2 => match parseUnary(rest2) {
        (exponent, rest3) => ("(${base}^${exponent})", rest3)
      },
      _ => (base, rest)
    }
  }

func parseUnary(tokens: [string]) -> (string, [string]) =
  match tokens {
    "-" :: rest => match parseUnary(rest) {
      (operand, rest2) => ("(-${operand})", rest2)
    },
    _ => parsePower(tokens)
  }

func parseMulDivRest(left: string, tokens: [string]) -> (string, [string]) =
  match tokens {
    "*" :: rest => match parseUnary(rest) {
      (right, rest2) => parseMulDivRest("(${left}*${right})", rest2)
    },
    "/" :: rest => match parseUnary(rest) {
      (right, rest2) => parseMulDivRest("(${left}/${right})", rest2)
    },
    _ => (left, tokens)
  }

func parseMulDiv(tokens: [string]) -> (string, [string]) =
  match parseUnary(tokens) {
    (left, rest) => parseMulDivRest(left, rest)
  }

func parseAddSubRest(left: string, tokens: [string]) -> (string, [string]) =
  match tokens {
    "+" :: rest => match parseMulDiv(rest) {
      (right, rest2) => parseAddSubRest("(${left}+${right})", rest2)
    },
    "-" :: rest => match parseMulDiv(rest) {
