def tokenize(expr):
    tokens = []
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', expr[i:j]))
            i = j
        elif c in '+-*/^()':
            tokens.append(('OP', c))
            i += 1
        else:
            i += 1
    return tokens


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse_expr(self):
        return self.parse_additive()

    def parse_additive(self):
        left = self.parse_multiplicative()
        while True:
            tok = self.peek()
            if tok and tok[1] in ('+', '-') and tok[0] == 'OP':
                op = self.consume()[1]
                right = self.parse_multiplicative()
                left = f'({left}{op}{right})'
            else:
                break
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while True:
            tok = self.peek()
            if tok and tok[1] in ('*', '/') and tok[0] == 'OP':
                op = self.consume()[1]
                right = self.parse_unary()
                left = f'({left}{op}{right})'
            else:
                break
        return left

    def parse_unary(self):
        tok = self.peek()
        if tok and tok[0] == 'OP' and tok[1] == '-':
            self.consume()
            operand = self.parse_unary()
            return f'(-{operand})'
        return self.parse_power()

    def parse_power(self):
        base = self.parse_primary()
        tok = self.peek()
        if tok and tok[0] == 'OP' and tok[1] == '^':
            self.consume()
            # Right-associative; exponent can be unary minus
            exp = self.parse_power_rhs()
            return f'({base}^{exp})'
        return base

    def parse_power_rhs(self):
        # The exponent: unary minus binds here (level 3 unary, but after ^)
        # unary minus may appear as exponent: 2^-3
        tok = self.peek()
        if tok and tok[0] == 'OP' and tok[1] == '-':
            self.consume()
            operand = self.parse_power_rhs_inner()
            return f'(-{operand})'
        return self.parse_power_rhs_inner()

    def parse_power_rhs_inner(self):
        # Parse primary then check for another ^
        base = self.parse_primary()
        tok = self.peek()
        if tok and tok[0] == 'OP' and tok[1] == '^':
            self.consume()
            exp = self.parse_power_rhs()
            return f'({base}^{exp})'
        return base

    def parse_primary(self):
        tok = self.peek()
        if tok and tok[0] == 'NUM':
            self.consume()
            return tok[1]
        if tok and tok[0] == 'OP' and tok[1] == '(':
            self.consume()
            val = self.parse_expr()
            closing = self.consume()  # should be ')'
            return val
        raise ValueError(f'Unexpected token: {tok}')


def parse_expression(expr):
    tokens = tokenize(expr)
    parser = Parser(tokens)
    result = parser.parse_expr()
    return result


def main():
    expressions = [
        '-2^2',
        '2^3^2',
        '8-4-2',
        '2^-3*4',
        '--5+1',
        '-2^-2^3',
        '(1+2)*-3',
        '100-10*-2^2',
    ]
    for expr in expressions:
        print(parse_expression(expr))


if __name__ == '__main__':
    main()

