type Color = Red | Black

type RBTree = Empty | Node(Color, RBTree, int, RBTree)

pure func balance(c: Color, l: RBTree, v: int, r: RBTree) -> RBTree =
  match (c, l, v, r) {
    (Black, Node(Red, Node(Red, a, x, b), y, c), z, d) => Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),
    (Black, Node(Red, a, x, Node(Red, b, y, c)), z, d) => Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),
    (Black, a, x, Node(Red, Node(Red, b, y, c), z, d)) => Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),
    (Black, a, x, Node(Red, b, y, Node(Red, c, z, d))) => Node(Red, Node(Black, a, x, b), y, Node(Black, c, z, d)),
    (col, left, val, right) => Node(col, left, val, right)
  }

pure func ins(x: int, tree: RBTree) -> RBTree =
  match tree {
    Empty => Node(Red, Empty, x, Empty),
    Node(c, l, v, r) =>
      if x < v then balance(c, ins(x, l), v, r)
      else if x > v then balance(c, l, v, ins(x, r))
      else Node(c, l, v, r)
  }

export func insert(x: int, tree: RBTree) -> RBTree =
  match ins(x, tree) {
    Node(_, l, v, r) => Node(Black, l, v, r),
    Empty => Empty
  }

pure func inorder(tree: RBTree) -> [int] =
  match tree {
    Empty => [],
    Node(_, l, v, r) => inorder(l) ++ [v] ++ inorder(r)
  }

func printList(xs: [int]) -> () ! {IO} =
  match xs {
    [] => (),
    x :: rest => {
      println(show(x));
      printList(rest)
    }
  }

export func main() -> () ! {IO} {
  let values = [7, 3, 18, 10, 22, 8, 11, 26];
  let tree = foldl(\acc x. insert(x, acc), Empty, values);
  let sorted = inorder(tree);
  printList(sorted)
}

