from __future__ import annotations

from dataclasses import dataclass
from enum import Enum, auto


class Color(Enum):
    Red = auto()
    Black = auto()


@dataclass(frozen=True)
class Empty:
    pass


EMPTY = Empty()


@dataclass(frozen=True)
class Node:
    color: Color
    left: RBTree
    value: int
    right: RBTree


RBTree = Empty | Node


def balance(color: Color, left: RBTree, value: int, right: RBTree) -> RBTree:
    match color, left, value, right:
        case (
            Color.Black,
            Node(Color.Red, Node(Color.Red, a, x, b), y, c),
            z,
            d,
        ):
            return Node(
                Color.Red,
                Node(Color.Black, a, x, b),
                y,
                Node(Color.Black, c, z, d),
            )
        case (
            Color.Black,
            Node(Color.Red, a, x, Node(Color.Red, b, y, c)),
            z,
            d,
        ):
            return Node(
                Color.Red,
                Node(Color.Black, a, x, b),
                y,
                Node(Color.Black, c, z, d),
            )
        case (
            Color.Black,
            a,
            x,
            Node(Color.Red, Node(Color.Red, b, y, c), z, d),
        ):
            return Node(
                Color.Red,
                Node(Color.Black, a, x, b),
                y,
                Node(Color.Black, c, z, d),
            )
        case (
            Color.Black,
            a,
            x,
            Node(Color.Red, b, y, Node(Color.Red, c, z, d)),
        ):
            return Node(
                Color.Red,
                Node(Color.Black, a, x, b),
                y,
                Node(Color.Black, c, z, d),
            )
        case _:
            return Node(color, left, value, right)


def insert(x: int, tree: RBTree) -> RBTree:
    def ins(t: RBTree) -> RBTree:
        match t:
            case Empty():
                return Node(Color.Red, EMPTY, x, EMPTY)
            case Node(color, left, value, right):
                if x < value:
                    return balance(color, ins(left), value, right)
                if x > value:
                    return balance(color, left, value, ins(right))
                return t
        raise RuntimeError("unreachable")

    result = ins(tree)
    match result:
        case Node(_, left, value, right):
            return Node(Color.Black, left, value, right)
        case Empty():
            return result
    return result


def inorder(tree: RBTree) -> list[int]:
    match tree:
        case Empty():
            return []
        case Node(_, left, value, right):
            return inorder(left) + [value] + inorder(right)
    raise RuntimeError("unreachable")


def main() -> None:
    values = [7, 3, 18, 10, 22, 8, 11, 26]
    tree: RBTree = EMPTY
    for value in values:
        tree = insert(value, tree)
    print(*inorder(tree))


if __name__ == "__main__":
    main()

