module benchmark/solution

type Operand = OpVar(string) | OpLit(int)

type Rhs =
  | RhsInput
  | RhsLit(int)
  | RhsBin(string, Operand, Operand)

type Inst = Inst(string, Rhs)

type Program = Prog([Inst], Operand)

type ValInfo = VConst(int) | VCopy(string) | VOpaque

pure func originalProgram() -> Program =
  Prog(
    [
      Inst("n", RhsInput),
      Inst("m", RhsInput),
      Inst("a", RhsLit(7)),
      Inst("a", RhsBin("-", OpVar("a"), OpLit(7))),
      Inst("c", RhsBin("*", OpVar("n"), OpVar("a"))),
      Inst("n", RhsBin("+", OpVar("n"), OpVar("c"))),
      Inst("q", RhsBin("*", OpVar("m"), OpLit(3))),
      Inst("e", RhsBin("*", OpVar("n"), OpLit(7))),
      Inst("f", RhsBin("-", OpVar("e"), OpVar("e"))),
      Inst("e", RhsBin("+", OpVar("e"), OpVar("f"))),
      Inst("r", RhsBin("*", OpVar("e"), OpLit(1)))
    ],
    OpVar("r")
  )

pure func lookupInt(key: string, m: [(string, int)]) -> int =
  match m {
    [] => 0,
    (k, v) :: rest => if k == key then v else lookupInt(key, rest)
  }

pure func updateInt(key: string, val: int, m: [(string, int)]) -> [(string, int)] =
  match m {
    [] => [(key, val)],
    (k, v) :: rest => if k == key then (key, val) :: rest else (k, v) :: updateInt(key, val, rest)
  }

pure func lookupStr(key: string, m: [(string, string)]) -> string =
  match m {
    [] => key,
    (k, v) :: rest => if k == key then v else lookupStr(key, rest)
  }

pure func updateStr(key: string, val: string, m: [(string, string)]) -> [(string, string)] =
  match m {
    [] => [(key, val)],
    (k, v) :: rest => if k == key then (key, val) :: rest else (k, v) :: updateStr(key, val, rest)
  }

pure func renameOp(op: Operand, env: [(string, string)]) -> Operand =
  match op {
    OpLit(k) => OpLit(k),
    OpVar(v) => OpVar(lookupStr(v, env))
  }

pure func pass1Inst(
  inst: Inst,
  counts: [(string, int)],
  env: [(string, string)]
) -> (Inst, [(string, int)], [(string, string)]) =
  match inst {
    Inst(varName, rhs) =>
      let count = lookupInt(varName, counts) in
      let ssaName = "${varName}.${show(count)}" in
      let newCounts = updateInt(varName, count + 1, counts) in
      let newEnv = updateStr(varName, ssaName, env) in
      let newRhs = match rhs {
        RhsInput => RhsInput,
        RhsLit(k) => RhsLit(k),
        RhsBin(op, x, y) => RhsBin(op, renameOp(x, env), renameOp(y, env))
      } in
      (Inst(ssaName, newRhs), newCounts, newEnv)
  }

pure func pass1List(
  insts: [Inst],
  counts: [(string, int)],
  env: [(string, string)]
) -> ([Inst], [(string, string)]) =
  match insts {
    [] => ([], env),
    i :: rest =>
      match pass1Inst(i, counts, env) {
        (newI, newCounts, newEnv) =>
          match pass1List(rest, newCounts, newEnv) {
            (restInsts, finalEnv) => (newI :: restInsts, finalEnv)
          }
      }
  }

pure func pass1(prog: Program) -> Program =
  match prog {
    Prog(insts, retOp) =>
      match pass1List(insts, [], []) {
        (newInsts, finalEnv) => Prog(newInsts, renameOp(retOp, finalEnv))
      }
  }

pure func lookupVal(key: string, t: [(string, ValInfo)]) -> ValInfo =
  match t {
    [] => VOpaque,
    (k, v) :: rest => if k == key then v else lookupVal(key, rest)
  }

pure func updateVal(key: string, v: ValInfo, t: [(string, ValInfo)]) -> [(string, ValInfo)] =
  (key, v) :: t

pure func subOp(op: Operand, t: [(string, ValInfo)]) -> Operand =
  match op {
    OpLit(k) => OpLit(k),
    OpVar(v) =>
      match lookupVal(v, t) {
        VConst(k) => OpLit(k),
        VCopy(src) => subOp(OpVar(src), t),
        VOpaque => OpVar(v)
      }
  }

pure func evalBinOp(op: string, a: int, b: int) -> int =
  if op == "+" then a + b
  else if op == "-" then a - b
  else if op == "*" then a * b
  else 0

pure func sameOp(x: Operand, y: Operand) -> bool =
  match (x, y) {
    (OpVar(a), OpVar(b)) => a == b,
    (OpLit(a), OpLit(b)) => a == b,
    _ => false
  }

pure func isZero(op: Operand) -> bool =
  match op {
    OpLit(n) => n == 0,
    _ => false
  }

pure func isOne(op: Operand) -> bool =
  match op {
    OpLit(n) => n == 1,
    _ => false
  }

pure func opToValInfo(op: Operand) -> ValInfo =
  match op {
    OpVar(v) => VCopy(v),
    OpLit(k) => VConst(k)
  }

pure func simplifyRhs(rhs: Rhs, t: [(string, ValInfo)]) -> Rhs =
  match rhs {
    RhsInput => RhsInput,
    RhsLit(k) => RhsLit(k),
    RhsBin(op, x, y) => RhsBin(op, subOp(x, t), subOp(y, t))
  }

pure func classify(target: string, rhs: Rhs) -> (ValInfo, Option[Inst]) =
  match rhs {
    RhsInput => (VOpaque, Some(Inst(target, RhsInput))),
    RhsLit(k) => (VConst(k), None),
    RhsBin(op, x, y) =>
      match (x, y) {
        (OpLit(a), OpLit(b)) => (VConst(evalBinOp(op, a, b)), None),
        _ =>
          if op == "-" && sameOp(x, y) then (VConst(0), None)
          else if op == "*" && (isZero(x) || isZero(y)) then (VConst(0), None)
          else if op == "*" && isOne(x) then (opToValInfo(y), None)
          else if op == "*" && isOne(y) then (opToValInfo(x), None)
          else if op == "+" && isZero(x) then (opToValInfo(y), None)
          else if op == "+" && isZero(y) then (opToValInfo(x), None)
          else if op == "-" && isZero(y) then (opToValInfo(x), None)
          else (VOpaque, Some(Inst(target, RhsBin(op, x, y))))
      }
  }

pure func pass2List(
  insts: [Inst],
  t: [(string, ValInfo)]
) -> ([Inst], [(string, ValInfo)]) =
  match insts {
    [] => ([], t),
    inst :: rest =>
      match inst {
        Inst(target, rhs) =>
          let simpRhs = simplifyRhs(rhs, t) in
          match classify(target, simpRhs) {
            (valInfo, optInst) =>
              let newT = updateVal(target, valInfo, t) in
              match pass2List(rest, newT) {
                (restKept, finalT) =>
                  match optInst {
                    Some(kept) => (kept :: restKept, finalT),
                    None => (restKept, finalT)
                  }
              }
          }
      }
  }

pure func pass2(prog: Program) -> Program =
  match prog {
    Prog(insts, retOp) =>
      match pass2List(insts, []) {
        (keptInsts, finalTable) =>
          Prog(keptInsts, subOp(retOp, finalTable))
      }
  }

pure func opVars(op: Operand) -> [string] =
  match op {
    OpVar(v) => [v],
    OpLit(_) => []
  }

pure func rhsVars(rhs: Rhs) -> [string] =
  match rhs {
    RhsInput => [],
    RhsLit(_) => [],
    RhsBin(_, x, y) => opVars(x) ++ opVars(y)
  }

pure func containsStr(s: string, xs: [string]) -> bool =
  match xs {
    [] => false,
    h :: t => if h == s then true else containsStr(s, t)
  }

pure func findDef(varName: string, insts: [Inst]) -> Option[Inst] =
  match insts {
    [] => None,
    inst :: rest =>
      match inst {
        Inst(target, _) =>
          if target == varName then Some(inst) else findDef(varName, rest)
      }
  }

pure func collectNeeded(
  worklist: [string],
  visited: [string],
  insts: [Inst]
) -> [string] =
  match worklist {
    [] => visited,
    v :: restWork =>
      if containsStr(v, visited) then
        collectNeeded(restWork, visited, insts)
      else
        let newVisited = v :: visited in
        match findDef(v, insts) {
          None => collectNeeded(restWork, newVisited, insts),
          Some(Inst(_, rhs)) =>
            let used = rhsVars(rhs) in
            collectNeeded(used ++ restWork, newVisited, insts)
        }
  }

pure func filterDce(insts: [Inst], needed: [string]) -> [Inst] =
  match insts {
    [] => [],
    inst :: rest =>
      match inst {
        Inst(target, _) =>
          if containsStr(target, needed) then
            inst :: filterDce(rest, needed)
          else
            filterDce(rest, needed)
      }
  }

pure func pass3(prog: Program) -> Program =
  match prog {
    Prog(insts, retOp) =>
      let initWork = opVars(retOp) in
      let needed = collectNeeded(initWork, [], insts) in
      let newInsts = filterDce(insts, needed) in
      Prog(newInsts, retOp)
  }

pure func showOp(op: Operand) -> string =
  match op {
    OpVar(v) => v,
    OpLit(k) => show(k)
  }

pure func showInst(inst: Inst) -> string =
  match inst {
    Inst(target, RhsInput) => "${target} = input",
    Inst(target, RhsLit(k)) => "${target} = ${show(k)}",
    Inst(target, RhsBin(op, x, y)) => "${target} = ${showOp(x)} ${op} ${showOp(y)}"
  }

func printInsts(insts: [Inst]) -> () ! {IO} =
  match insts {
    [] => (),
    i :: rest => {
      println(showInst(i));
      printInsts(rest)
    }
  }

func printProgram(prog: Program) -> () ! {IO} =
  match prog {
    Prog(insts, retOp) => {
      printInsts(insts);
      println("return ${showOp(retOp)}")
    }
  }

export func main() -> () ! {IO} {
  let prog0 = originalProgram();
  let prog1 = pass1(prog0);
  let prog2 = pass2(prog1);
  let prog3 = pass3(prog2);
  printProgram(prog3)
}

