def main():
    # Represent the program as a list of (variable, instruction) tuples
    # instruction is one of:
    #   ('input',)
    #   ('lit', value)
    #   ('op', op, operand1, operand2)  where operand is ('var', name) or ('lit', value)

    program = [
        ('n', ('input',)),
        ('m', ('input',)),
        ('a', ('lit', 7)),
        ('a', ('op', '-', ('var', 'a'), ('lit', 7))),
        ('c', ('op', '*', ('var', 'n'), ('var', 'a'))),
        ('n', ('op', '+', ('var', 'n'), ('var', 'c'))),
        ('q', ('op', '*', ('var', 'm'), ('lit', 3))),
        ('e', ('op', '*', ('var', 'n'), ('lit', 7))),
        ('f', ('op', '-', ('var', 'e'), ('var', 'e'))),
        ('e', ('op', '+', ('var', 'e'), ('var', 'f'))),
        ('r', ('op', '*', ('var', 'e'), ('lit', 1))),
    ]
    return_var = 'n'
    return_var = 'r'

    # PASS 1: SSA renaming
    # Track count of assignments per variable
    var_count = {}
    # Track current SSA name for each variable
    var_current = {}

    ssa_instructions = []  # list of (ssa_name, instruction_with_ssa_operands)

    def resolve_operand_ssa(operand, var_current):
        if operand[0] == 'lit':
            return operand
        elif operand[0] == 'var':
            name = operand[1]
            ssa_name = var_current[name]
            return ('ssa', ssa_name)

    for (var, instr) in program:
        # First, resolve operands using current SSA names
        if instr[0] == 'input':
            new_instr = ('input',)
        elif instr[0] == 'lit':
            new_instr = instr
        elif instr[0] == 'op':
            op = instr[1]
            op1 = resolve_operand_ssa(instr[2], var_current)
            op2 = resolve_operand_ssa(instr[3], var_current)
            new_instr = ('op', op, op1, op2)

        # Define new SSA name for var
        count = var_count.get(var, 0)
        ssa_name = f"{var}.{count}"
        var_count[var] = count + 1
        var_current[var] = ssa_name

        ssa_instructions.append((ssa_name, new_instr))

    # Resolve return variable
    return_ssa = var_current[return_var]

    # PASS 2: Forward simplification
    # Table maps SSA name -> ('const', value) | ('copy', ssa_name) | ('opaque',)
    table = {}
    kept = set()  # SSA names whose instructions are kept

    def chase_copy(name):
        visited = set()
        while True:
            if name in visited:
                break
            visited.add(name)
            entry = table.get(name)
            if entry is None or entry[0] != 'copy':
                break
            name = entry[1]
        return name

    def substitute_operand(operand):
        """Returns ('lit', value) or ('ssa', ssa_name)"""
        if operand[0] == 'lit':
            return operand
        elif operand[0] == 'ssa':
            name = operand[1]
            entry = table.get(name, ('opaque',))
            if entry[0] == 'const':
                return ('lit', entry[1])
            elif entry[0] == 'copy':
                chased = chase_copy(name)
                return ('ssa', chased)
            else:
                return ('ssa', name)

    simplified_instrs = []  # (ssa_name, simplified_instr or None if deleted)

    for (ssa_name, instr) in ssa_instructions:
        if instr[0] == 'input':
            table[ssa_name] = ('opaque',)
            kept.add(ssa_name)
            simplified_instrs.append((ssa_name, instr))
        elif instr[0] == 'lit':
            table[ssa_name] = ('const', instr[1])
            simplified_instrs.append((ssa_name, None))
        elif instr[0] == 'op':
            op = instr[1]
            sub1 = substitute_operand(instr[2])
            sub2 = substitute_operand(instr[3])

            # Try to classify
            is_lit1 = sub1[0] == 'lit'
            is_lit2 = sub2[0] == 'lit'

            classified = False

            # Both operands are literals -> compute
            if is_lit1 and is_lit2:
                v1, v2 = sub1[1], sub2[1]
                if op == '+':
                    result = v1 + v2
                elif op == '-':
                    result = v1 - v2
                elif op == '*':
                    result = v1 * v2
                table[ssa_name] = ('const', result)
                simplified_instrs.append((ssa_name, None))
                classified = True

            if not classified and op == '-' and not is_lit1 and not is_lit2:
                # x - x same SSA name
                if sub1[1] == sub2[1]:
                    table[ssa_name] = ('const', 0)
                    simplified_instrs.append((ssa_name, None))
                    classified = True

            if not classified and op == '*':
                if (is_lit1 and sub1[1] == 0) or (is_lit2 and sub2[1] == 0):
                    table[ssa_name] = ('const', 0)
                    simplified_instrs.append((ssa_name, None))
                    classified = True

            if not classified and op == '*':
                if is_lit1 and sub1[1] == 1:
                    # 1 * x -> copy(x)
                    src = sub2[1] if not is_lit2 else None
                    if src is not None:
                        table[ssa_name] = ('copy', src)
                        simplified_instrs.append((ssa_name, None))
                        classified = True
                elif is_lit2 and sub2[1] == 1:
                    # x * 1 -> copy(x)
                    src = sub1[1] if not is_lit1 else None
                    if src is not None:
                        table[ssa_name] = ('copy', src)
                        simplified_instrs.append((ssa_name, None))
                        classified = True

            if not classified and op == '+':
                if is_lit1 and sub1[1] == 0:
                    src = sub2[1] if not is_lit2 else None
                    if src is not None:
                        table[ssa_name] = ('copy', src)
                        simplified_instrs.append((ssa_name, None))
                        classified = True
                elif is_lit2 and sub2[1] == 0:
                    src = sub1[1] if not is_lit1 else None
                    if src is not None:
                        table[ssa_name] = ('copy', src)
                        simplified_instrs.append((ssa_name, None))
                        classified = True

            if not classified and op == '-':
                if is_lit2 and sub2[1] == 0:
                    src = sub1[1] if not is_lit1 else None
                    if src is not None:
                        table[ssa_name] = ('copy', src)
                        simplified_instrs.append((ssa_name, None))
                        classified = True

            if not classified:
                # Opaque, keep instruction with substituted operands
                table[ssa_name] = ('opaque',)
                kept.add(ssa_name)
                simplified_instrs.append((ssa_name, ('op', op, sub1, sub2)))

    # Resolve return operand
    ret_entry = table.get(return_ssa, ('opaque',))
    if ret_entry[0] == 'const':
        return_operand = ('lit', ret_entry[1])
    elif ret_entry[0] == 'copy':
        chased = chase_copy(return_ssa)
        entry2 = table.get(chased, ('opaque',))
        if entry2[0] == 'const':
            return_operand = ('lit', entry2[1])
        else:
            return_operand = ('ssa', chased)
    else:
        return_operand = ('ssa', return_ssa)

    # PASS 3: Dead code elimination
    # Find all SSA names transitively referenced from return_operand
    needed = set()

    def collect_needed_from_operand(operand):
        if operand[0] == 'ssa':
            collect_needed(operand[1])

    def collect_needed(ssa_name):
        if ssa_name in needed:
            return
        needed.add(ssa_name)
        # Find the instruction for this ssa_name
        for (name, instr) in simplified_instrs:
            if name == ssa_name and instr is not None:
                if instr[0] == 'op':
                    collect_needed_from_operand(instr[2])
                    collect_needed_from_operand(instr[3])
                break

    if return_operand[0] == 'ssa':
        collect_needed(return_operand[1])

    # Print surviving instructions
    def format_operand(operand):
        if operand[0] == 'lit':
            return str(operand[1])
        elif operand[0] == 'ssa':
            return operand[1]
        elif operand[0] == 'input':
            return 'input'
        return str(operand)

    for (ssa_name, instr) in simplified_instrs:
        if instr is None:
            continue
        if ssa_name not in kept:
            continue
        if ssa_name not in needed:
            continue
        if instr[0] == 'input':
            print(f"{ssa_name} = input")
        elif instr[0] == 'op':
            op = instr[1]
            o1 = format_operand(instr[2])
            o2 = format_operand(instr[3])
            print(f"{ssa_name} = {o1} {op} {o2}")

    print(f"return {format_operand(return_operand)}")


if __name__ == "__main__":
    main()

