from dataclasses import dataclass
from typing import Generic, TypeVar

T = TypeVar('T')
E = TypeVar('E')


@dataclass(frozen=True)
class Ok(Generic[T]):
    value: T


@dataclass(frozen=True)
class Err(Generic[E]):
    reason: E


type Result[T, E] = Ok[T] | Err[E]


@dataclass(frozen=True)
class Idle:
    pass


@dataclass(frozen=True)
class HasCredit:
    cents: int


@dataclass(frozen=True)
class Dispensing:
    change: int


type State = Idle | HasCredit | Dispensing


@dataclass(frozen=True)
class Insert:
    cents: int


@dataclass(frozen=True)
class Select:
    code: int


@dataclass(frozen=True)
class DispenseDone:
    pass


type Event = Insert | Select | DispenseDone


PRICES: dict[int, int] = {1: 125, 2: 75, 3: 100}


def step(state: State, event: Event) -> Result[State, str]:
    match (state, event):
        case (Idle(), Insert(cents=n)):
            return Ok(HasCredit(n))
        case (Idle(), Select()):
            return Err("no_credit")
        case (Idle(), DispenseDone()):
            return Err("not_dispensing")
        case (HasCredit(cents=c), Insert(cents=n)):
            return Ok(HasCredit(c + n))
        case (HasCredit(cents=c), Select(code=code)):
            if code not in PRICES:
                return Err("unknown_item")
            price = PRICES[code]
            if c < price:
                return Err("insufficient_funds")
            return Ok(Dispensing(c - price))
        case (HasCredit(), DispenseDone()):
            return Err("not_dispensing")
        case (Dispensing(), Insert()):
            return Err("busy")
        case (Dispensing(), Select()):
            return Err("busy")
        case (Dispensing(), DispenseDone()):
            return Ok(Idle())


def format_result(result: Result[State, str]) -> str:
    match result:
        case Ok(value=Idle()):
            return "ok: IDLE"
        case Ok(value=HasCredit(cents=n)):
            return f"ok: CREDIT({n})"
        case Ok(value=Dispensing(change=ch)):
            return f"ok: DISPENSING({ch})"
        case Err(reason=r):
            return f"err: {r}"


def main() -> None:
    events: list[Event] = [
        Insert(50),
        Select(1),
        Insert(100),
        Select(1),
        Insert(50),
        DispenseDone(),
        Select(2),
        Insert(100),
        Select(2),
        DispenseDone(),
    ]

    state: State = Idle()

    for event in events:
        result = step(state, event)
        print(format_result(result))
        match result:
            case Ok(value=new_state):
                state = new_state
            case Err():
                pass


if __name__ == "__main__":
    main()

