module benchmark/solution

import std/list (sortBy)

-- Lehmer LCG parameters
-- x[n+1] = (48271 * x[n]) mod 2147483647
-- Since 48271 * 2147483647 can overflow 64-bit signed ints if we are not careful,
-- we use 64-bit integer arithmetic which AILANG natively provides (signed 64-bit).
-- Max value = 2147483646. 48271 * 2147483646 ≈ 1.03e14, well within int64 range (~9e18).

pure func nextRand(x: int) -> int =
  (48271 * x) % 2147483647

pure func generateStream(n: int, current: int, acc: [int]) -> [int] =
  if n == 0 then acc
  else {
    let nxt = nextRand(current);
    generateStream(n - 1, nxt, acc ++ [nxt])
  }

-- Sum helper
pure func sumList(xs: [int]) -> int =
  match xs {
    [] => 0,
    x :: rest => x + sumList(rest)
  }

-- Sum of first k elements
pure func sumTop(xs: [int], k: int) -> int =
  if k <= 0 then 0
  else match xs {
    [] => 0,
    x :: rest => x + sumTop(rest, k - 1)
  }

-- Descending comparator for sorting
pure func cmpDesc(a: int, b: int) -> int =
  if b > a then 1 else if b < a then -1 else 0

export func main() -> () ! {IO} {
  let stream = generateStream(2000, 20260708, []);

  -- nth/last extraction or direct list traversal for x[2000]
  -- stream has 2000 elements, index 1999 is x[2000]
  -- Let's define a helper to get nth element (0-indexed)
  letrec getNth = \xs. \i.
    match xs {
      [] => 0,
      x :: rest => if i == 0 then x else getNth(rest, i - 1)
    };

  let x2000 = getNth(stream, 1999);

  -- Sort descending to get 10 largest
  let sortedDesc = sortBy(cmpDesc, stream);
  let top10Sum = sumTop(sortedDesc, 10);

  -- Sum of all elements modulo 1000000007
  letrec sumMod = \xs. \acc.
    match xs {
      [] => acc,
      x :: rest => sumMod(rest, (acc + x) % 1000000007)
    };
  let totalSumMod = sumMod(stream, 0);

  println(show(x2000));
  println(show(top10Sum));
  println(show(totalSumMod))
}

