type Expr = Const(int) | Var(string) | Add(Expr, Expr) | Mul(Expr, Expr)

func diff(expr: Expr, var: string) -> Expr =
  match expr {
    Const(_) => Const(0),
    Var(v) => if v == var then Const(1) else Const(0),
    Add(f, g) => Add(diff(f, var), diff(g, var)),
    Mul(f, g) => Add(Mul(f, diff(g, var)), Mul(g, diff(f, var)))
  }

func simplify(expr: Expr) -> Expr =
  match expr {
    Const(c) => Const(c),
    Var(v) => Var(v),
    Add(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match (sa, sb) {
        (Const(0), e) => e,
        (e, Const(0)) => e,
        (x, y) => Add(x, y)
      }
    },
    Mul(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match (sa, sb) {
        (Const(0), _) => Const(0),
        (_, Const(0)) => Const(0),
        (Const(1), e) => e,
        (e, Const(1)) => e,
        (x, y) => Mul(x, y)
      }
    }
  }

func showExpr(expr: Expr) -> string =
  match expr {
    Const(n) => show(n),
    Var(v) => v,
    Add(a, b) => "(${showExpr(a)} + ${showExpr(b)})",
    Mul(a, b) => "(${showExpr(a)} * ${showExpr(b)})"
  }

export func main() -> () ! {IO} {
  let expr = Add(Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))), Const(5));
  let d = diff(expr, "x");
  let s = simplify(d);
  println(showExpr(s))
}

