type Tree = Leaf(int) | Node(Tree, int, Tree)

pure func mapTree(f: int -> int, t: Tree) -> Tree =
  match t {
    Leaf(v) => Leaf(f(v)),
    Node(l, v, r) => Node(mapTree(f, l), f(v), mapTree(f, r))
  }

pure func foldTree(f: (int, int) -> int, acc: int, t: Tree) -> int =
  match t {
    Leaf(v) => f(acc, v),
    Node(l, v, r) => {
      let acc1 = foldTree(f, acc, l);
      let acc2 = f(acc1, v);
      foldTree(f, acc2, r)
    }
  }

pure func treeToList(t: Tree) -> [int] =
  match t {
    Leaf(v) => [v],
    Node(l, v, r) => treeToList(l) ++ [v] ++ treeToList(r)
  }

pure func maxInt(a: int, b: int) -> int =
  if a > b then a else b

pure func treeDepth(t: Tree) -> int =
  match t {
    Leaf(_) => 1,
    Node(l, _, r) => 1 + maxInt(treeDepth(l), treeDepth(r))
  }

