from dataclasses import dataclass
from typing import Callable, TypeVar

A = TypeVar('A')
B = TypeVar('B')


@dataclass
class Leaf:
    value: int


@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'


Tree = Leaf | Node


def map_tree(fn: Callable[[int], int], tree: Tree) -> Tree:
    match tree:
        case Leaf(value):
            return Leaf(fn(value))
        case Node(left, value, right):
            return Node(map_tree(fn, left), fn(value), map_tree(fn, right))


def fold_tree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    match tree:
        case Leaf(value):
            return fn(acc, value)
        case Node(left, value, right):
            left_acc = fold_tree(fn, acc, left)
            combined = fn(left_acc, value)
            return fold_tree(fn, combined, right)


def tree_to_list(tree: Tree) -> list[int]:
    match tree:
        case Leaf(value):
            return [value]
        case Node(left, value, right):
            return tree_to_list(left) + [value] + tree_to_list(right)


def tree_depth(tree: Tree) -> int:
    match tree:
        case Leaf():
            return 1
        case Node(left, _, right):
            return 1 + max(tree_depth(left), tree_depth(right))


def double(x: int) -> int:
    return x * 2


def add(a: int, b: int) -> int:
    return a + b


def main() -> None:
    tree: Tree = Node(Node(Leaf(1), 2, Leaf(3)), 4, Node(Leaf(5), 6, Leaf(7)))

    print(tree_to_list(tree))
    print(tree_to_list(map_tree(double, tree)))
    print(fold_tree(add, 0, tree))
    print(tree_depth(tree))


