        TInt => TInt,
        TBool => TBool,
        TFunc(arg, res) => TFunc(apply(s, arg), apply(s, res))
    }

pure func lookupSubst(s: Subst, name: string) -> Type =
    match s {
        [] => TVar(name),
        (v, t) :: rest => if v == name then t else lookupSubst(rest, name)
    }

pure func compose(s1: Subst, s2: Subst) -> Subst =
    let s2Applied = map(func(pair: (string, Type)) -> (string, Type) {
        match pair {
            (v, t) => (v, apply(s1, t))
        }
    }, s2);
    s1 ++ s2Applied

pure func unify(t1: Type, t2: Type) -> Result[Subst, string] =
    match (t1, t2) {
        (TInt, TInt) => Ok([]),
        (TBool, TBool) => Ok([]),
        (TVar(a), _) => Ok([(a, t2)]),
        (_, TVar(a)) => Ok([(a, t1)]),
        (TFunc(a1, r1), TFunc(a2, r2)) =>
            match unify(a1, a2) {
                Err(e) => Err(e),
                Ok(s1) =>
                    match unify(apply(s1, r1), apply(s1, r2)) {
                        Err(e) => Err(e),
                        Ok(s2) => Ok(compose(s2, s1))
                    }
            },
        _ => Err("type mismatch")
    }

pure func showType(t: Type) -> string =
    match t {
        TVar(name) => "TVar(\"${name}\")",
        TInt => "TInt",
        TBool => "TBool",
        TFunc(a, r) => "TFunc(${showType(a)}, ${showType(r)})"
    }

export func main() -> () ! {IO} {
    let t1 = TFunc(TVar("a"), TInt);
    let t2 = TFunc(TBool, TVar("b"));
    match unify(t1, t2) {
        Ok(subst) => {
            let aVal = apply(subst, TVar("a"));
            let bVal = apply(subst, TVar("b"));
            println("a = ${showType(aVal)}");
            println("b = ${showType(bVal)}")
        },
        Err(msg) => println("Error: ${msg}")
    }
}

