from __future__ import annotations

from dataclasses import dataclass


class Type:
    pass


@dataclass(frozen=True)
class TVar(Type):
    name: str

    def __str__(self) -> str:
        return f"TVar({self.name!r})"


@dataclass(frozen=True)
class TIntType(Type):
    def __str__(self) -> str:
        return "TInt"


@dataclass(frozen=True)
class TBoolType(Type):
    def __str__(self) -> str:
        return "TBool"


@dataclass(frozen=True)
class TFunc(Type):
    arg: Type
    result: Type

    def __str__(self) -> str:
        return f"TFunc({self.arg}, {self.result})"


TInt = TIntType()
TBool = TBoolType()

Subst = list[tuple[str, Type]]


class UnificationError(Exception):
    pass


def apply(subst: Subst, t: Type) -> Type:
    match t:
        case TVar(name):
            for var, ty in subst:
                if var == name:
                    return apply(subst, ty) if isinstance(ty, TVar) and ty.name != name else ty
            return t
        case TFunc(arg, result):
            return TFunc(apply(subst, arg), apply(subst, result))
        case _:
            return t


def unify(t1: Type, t2: Type) -> Subst:
    match (t1, t2):
        case (TIntType(), TIntType()):
            return []
        case (TBoolType(), TBoolType()):
            return []
        case (TVar(a), _):
            return [(a, t2)]
        case (_, TVar(a)):
            return [(a, t1)]
        case (TFunc(a1, r1), TFunc(a2, r2)):
            s1 = unify(a1, a2)
            s2 = unify(apply(s1, r1), apply(s1, r2))
            return s1 + s2
        case _:
            raise UnificationError(f"Cannot unify {t1} with {t2}")


def main() -> None:
    t1 = TFunc(TVar("a"), TInt)
    t2 = TFunc(TBool, TVar("b"))
    try:
        subst = unify(t1, t2)
        for var, ty in subst:
            print(f"{var} = {ty}")
    except UnificationError as exc:
        print(f"Unification failed: {exc}")


if __name__ == "__main__":
    main()

