import math
from typing import Generic, TypeVar, Callable

T = TypeVar("T")
R = TypeVar("R")

class Option(Generic[T]):
    def map(self, func: Callable[[T], R]) -> 'Option[R]':
        match self:
            case Some(value):
                return Some(func(value))
            case _:
                return Nothing()

    def flatMap(self, func: Callable[[T], 'Option[R]']) -> 'Option[R]':
        match self:
            case Some(value):
                return func(value)
            case _:
                return Nothing()

class Some(Option[T]):
    __match_args__ = ("value",)
    def __init__(self, value: T):
        self.value = value
    def __str__(self) -> str:
        return f"Some({self.value})"

class Nothing(Option[T]):
    def __str__(self) -> str:
        return "None"

def safeDiv(a: int, b: int) -> Option[int]:
    if b == 0:
        return Nothing()
    return Some(a // b)

def safeSqrt(x: int) -> Option[int]:
    if x < 0:
        return Nothing()
    return Some(math.isqrt(x))

def chain(a: int, b: int, c: int) -> Option[int]:
    return safeDiv(a, b).flatMap(safeSqrt).map(lambda x: x + c)

if __name__ == "__main__":
    print(f"chain(100, 4, 1)     -> {chain(100, 4, 1)}")
    print(f"chain(100, 0, 1)     -> {chain(100, 0, 1)}")
    print(f"chain(-4, 1, 10)     -> {chain(-4, 1, 10)}")
    print(f"chain(16, 4, -3)     -> {chain(16, 4, -3)}")

